Object.assign(window.TEM8_DICTIONARY, {"violate":{"oxford":{"phon":"ˈvaɪəleɪt","pos":"verb","senses":[{"en":"to go against or refuse to obey a law, an agreement, etc.","cn":"违反，违犯，违背（法律、协议等）","lab":"formal","ex":{"en":"to violate international law","cn":"违反国际法"}},{"en":"to upset or not respect somebody’s peace, privacy, etc.","cn":"侵犯（隐私等）；使人不得安宁；搅扰","lab":"formal","ex":{"en":"She accused the press photographers of violating her privacy.","cn":"她指责新闻摄影记者侵犯了她的隐私。"}},{"en":"to damage or destroy a holy or special place","cn":"亵渎，污损（神圣之地）","ex":{"en":"to violate a grave","cn":"亵渎坟墓"}},{"en":"to force somebody to have sex","cn":"强奸；奸污","lab":"literary or old-fashioned","ex":{"en":"He had drugged her and then violated her.","cn":"他给她下了药，然后侵犯了她。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"违反，违背，违犯（协议、法律或承诺）","en":"If someone violates an agreement, law, or promise, they break it.","ex":{"en":"They went to prison because they violated the law","cn":"他们触犯了法律，因此坐了牢。"}},{"pos":"VERB 动词","cn":"侵犯（隐私）;搅扰;打搅","en":"If you violate someone's privacy or peace, you disturb it.","ex":{"en":"These men were violating her family's privacy.","cn":"这些人侵犯了她的家庭隐私。"}},{"pos":"VERB 动词","cn":"污损;亵渎","en":"If someone violates a special place, for example a grave, they damage it or treat it with disrespect.","ex":{"en":"Detectives are still searching for those who violated the graveyard.","cn":"侦探们仍在搜捕那些亵渎了墓园的家伙。"}}]},"media":{"uk":"media/uk/violate__gb_1.mp3","us":"media/us/violate__us_1.mp3"},"examples":[{"en":"She accused the press photographers of violating her privacy.","cn":"她指责新闻摄影记者侵犯了她的隐私。"},{"en":"They were in open violation of the treaty.","cn":"他们公然违反条约。"}]},"viewpoint":{"media":{"uk":"media/uk/viewpoint__gb_1.mp3","us":"media/us/viewpoint__us_1.mp3"},"oxford":{"phon":"ˈvjuːpɔɪnt","pos":"noun","senses":[{"en":"a way of thinking about a subject","cn":"观点；看法","ex":{"en":"Try looking at things from a different viewpoint.","cn":"试试从不同的角度看待事物。"}},{"en":"a direction or place from which you look at something","cn":"角度","ex":{"en":"The artist has painted the scene from various viewpoints.","cn":"那位画家从各种角度把这一景色画了下来。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"观点;看法；角度","en":"Someone's viewpoint is the way that they think about things in general, or the way they think about a particular thing.","ex":{"en":"The novel is shown from the girl's viewpoint","cn":"这部小说是从这个女孩的视角来叙述的。"}},{"pos":"N-COUNT 可数名词","cn":"视角;角度；观察点","en":"A viewpoint is a place from which you can get a good view of something.","ex":{"en":"You have to know where to stand for a good viewpoint.","cn":"你得知道站在哪里观察角度比较理想。"}}]},"examples":[{"en":"The artist has painted the scene from various viewpoints.","cn":"那位画家从各种角度把这一景色画了下来。"},{"en":"She will have her own viewpoint on the matter.","cn":"她对这个问题会有她自己的看法。"}]},"village":{"media":{"uk":"media/uk/village__gb_1.mp3","us":"media/us/village__us_1.mp3"},"oxford":{"phon":"ˈvɪlɪdʒ","pos":"noun","senses":[{"en":"a very small town located in a country area","cn":"村庄；村镇","g":"[countable]","lab":"especially British English","ex":{"en":"We visited towns and villages all over Spain.","cn":"我们走遍了西班牙的城镇和村庄。"}},{"en":"the people who live in a village","cn":"乡村居民；村民","g":"[singular]","lab":"especially British English","ex":{"en":"The whole village was invited to the party.","cn":"全村的人都获邀参加聚会。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"乡村;村庄;村落","en":"A village consists of a group of houses, together with other buildings such as a church and a school, in a country area.","ex":{"en":"He lives quietly in the country in a village near Lahti.","cn":"他在拉赫蒂附近的一个乡村里过着平静的日子。"}}]},"examples":[{"en":"We visited towns and villages all over Spain.","cn":"我们走遍了西班牙的城镇和村庄。"},{"en":"Her books are about village life.","cn":"她的书是关于乡村生活的。"}]},"virtual":{"media":{"uk":"media/uk/virtual__gb_1.mp3","us":"media/us/virtual__us_1.mp3"},"oxford":{"phon":"ˈvɜːtʃuəl","pos":"adjective","senses":[{"en":"made to appear to exist by the use of computer software, for example on the internet","cn":"（通过计算机软件，如在互联网上）模拟的，虚拟的","lab":"computing","ex":{"en":"a system to help programmers create virtual environments","cn":"帮助程序员创建虚拟环境的系统"}},{"en":"almost or very nearly the thing described, so that any slight difference is not important","cn":"很接近的；几乎…的；事实上的；实际上的；实质上的","ex":{"en":"The company has a virtual monopoly in this area of trade.","cn":"这家公司实质上已经垄断了这种贸易。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"几乎的;实际上的;事实上的","en":"You can use virtual to indicate that something is so nearly true that for most purposes it can be regarded as true.","ex":{"en":"Argentina came to a virtual standstill while the game was being played","cn":"在比赛进行的时候，阿根廷全国几乎陷入了停顿状态。"}},{"pos":"ADJ 形容词","cn":"虚拟的;模拟的","en":"Virtual objects and activities are generated by a computer to simulate real objects and activities.","ex":{"en":"Up to four players can compete in a virtual world of role playing","cn":"最多可以有4个玩家在一个虚拟世界中扮演角色互相拼杀。"}}]},"examples":[{"en":"New technology has enabled development of an online ‘virtual library’.","cn":"新技术已经使在线“虚拟图书馆”的发展成为可能。"},{"en":"The country was sliding into a state of virtual civil war.","cn":"这个国家实际上正逐渐进入内战状态。"}]},"vitality":{"media":{"uk":"media/uk/vitality__gb_1.mp3","us":"media/us/vitality__us_1.mp3"},"oxford":{"phon":"vaɪˈtæləti","pos":"noun","senses":[{"en":"energy and enthusiasm","cn":"生命力；活力；热情","ex":{"en":"She is bursting with vitality and new ideas.","cn":"她朝气蓬勃，满脑子新主意。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"活力;生命力;热情","en":"If you say that someone or something has vitality, you mean that they have great energy and liveliness.","ex":{"en":"Without continued learning, graduates will lose their intellectual vitality","cn":"如果不继续学习，毕业生就会失去思想上的活力。"}}]},"examples":[{"en":"She is bursting with vitality and new ideas.","cn":"她朝气蓬勃，满脑子新主意。"},{"en":"Despite her eighty years, Elsie was full of vitality.","cn":"尽管已80岁了﹐埃尔茜依然充满活力。"}]},"visibility":{"oxford":{"phon":"ˌvɪzəˈbɪləti","pos":"noun","senses":[{"en":"how far or well you can see, especially as affected by the light or the weather","cn":"可见度；能见度；能见距离","ex":{"en":"good/poor/bad/zero visibility","cn":"能见度高／低／差／为零"}},{"en":"the fact of attracting attention or being easy to see","cn":"可见性；明显性；引人注目","ex":{"en":"The advertisements were intended to increase the company's visibility in the marketplace (= to make people more aware of its products and services).","cn":"那些广告旨在使这家公司在市场中更加引人注目。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"可见度;能见度;能见距离","en":"Visibility means how far or how clearly you can see in particular weather conditions.","ex":{"en":"Visibility was poor.","cn":"能见度很差。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"可见性;关注程度;引人注目的程度","en":"If you refer to the visibility of something such as a situation or problem, you mean how much it is seen or noticed by other people.","ex":{"en":"The plight of the Kurds gained global visibility.","cn":"库尔德人的苦难引起了全球关注。"}}]},"media":{"uk":"media/uk/visibility__gb_1.mp3","us":"media/us/visibility__us_1.mp3"},"examples":[{"en":"The advertisements were intended to increase the company's visibility in the marketplace (= to make people more aware of their products and services).","cn":"那些广告旨在使这家公司在市场中更加引人注目。"},{"en":"Visibility was down to about 100 metres in the fog.","cn":"雾中的能见距离降到了大约 100 米。"}]},"vibrant":{"oxford":{"phon":"ˈvaɪbrənt","pos":"adjective","senses":[{"en":"full of life and energy","cn":"充满生机的；生气勃勃的；精力充沛的","ex":{"en":"a vibrant city","cn":"充满生机的城市"}},{"en":"very bright and strong","cn":"鲜艳的；醒目的","ex":{"en":"The room was decorated in vibrant reds and yellows.","cn":"那房间是由鲜艳的红黄两色装饰的。"}},{"en":"loud and powerful","cn":"响亮的；洪亮的；强劲的","ex":{"en":"vibrant rhythms","cn":"强有力的节奏"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"充满生气的;精力充沛的;活跃的","en":"Someone or something that is vibrant is full of life, energy, and enthusiasm.","ex":{"en":"Tom felt himself being drawn towards her vibrant personality","cn":"汤姆感觉自己被她充满朝气的个性所吸引。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（色彩）明亮的，鲜亮的","en":"Vibrant colours are very bright and clear.","ex":{"en":"Horizon Blue, Corn Yellow and Pistachio Green are just three of the vibrant colours in this range","cn":"天际蓝、玉米黄、淡草绿色只是这一色系内的3种亮色。"}}]},"media":{"uk":"media/uk/vibrant__gb_1.mp3","us":"media/us/vibrant__us_1.mp3"},"examples":[{"en":"The room was decorated in vibrant reds and yellows.","cn":"那房间是由鲜艳的红黄两色装饰的。"},{"en":"Thailand is at its most vibrant during the New Year celebrations.","cn":"在欢度新年期间，泰国举国欢腾。"}]},"vista":{"media":{"uk":"media/uk/vista__gb_1.mp3","us":"media/us/vista__us_1.mp3"},"oxford":{"phon":"ˈvɪstə","pos":"noun","senses":[{"en":"a beautiful view, for example, of the countryside, a city, etc.","cn":"（农村、城市等的）景色，景观","lab":"literary","ex":{"en":"She turned her gaze towards the soothing vista of river and fields.","cn":"她把目光转向河流和田野的舒缓景色。"}},{"en":"a range of things that might happen in the future","cn":"（未来可能发生的）一系列情景，一连串事情","lab":"formal","ex":{"en":"This new job could open up whole new vistas for her.","cn":"这份新工作可能给她开辟全新的前景。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（尤指从高处看到的）景观，全景","en":"A vista is a view from a particular place, especially a beautiful view from a high place.","ex":{"en":"From my bedroom window I looked out on a crowded vista of hills and rooftops.","cn":"我从卧室窗口望去，远处尽是连绵的山峦和屋顶。"}},{"pos":"N-COUNT 可数名词","cn":"展望;前景","en":"A vista is a vision of a situation or of a range of possibilities.","ex":{"en":"These uprisings come from desperation and a vista of a future without hope.","cn":"发生这些暴动是因为人们被逼上了绝路，未来看不到一点儿希望。"}}]},"examples":[{"en":"This new job could open up whole new vistas for her.","cn":"这项新工作可能给她开辟全新的前景。"},{"en":"stunning vistas of the Norfolk coast","cn":"诺福克海岸迷人的景色"}]},"vision":{"media":{"uk":"media/uk/vision__gb_1.mp3","us":"media/us/vision__us_1.mp3"},"oxford":{"phon":"ˈvɪʒn","pos":"noun","senses":[{"en":"the ability to see; the area that you can see from a particular position","cn":"视力；视野","g":"[uncountable]","ex":{"en":"to have good/perfect/poor/blurred/normal vision","cn":"视力好／极好／差／模糊／正常"}},{"en":"an idea or a picture in your imagination","cn":"想象；幻象","g":"[countable]","ex":{"en":"Our job is to guide a client and develop a strategic vision.","cn":"我们的工作是指导客户并制定战略愿景。"}},{"en":"a dream or similar experience, especially of a religious kind","cn":"梦幻；幻象；神示；异象","g":"[countable]","ex":{"en":"The idea came to her in a vision.","cn":"她在神示中想到了这个主意。"}},{"en":"the ability to think about or plan the future with great imagination and intelligence","cn":"想象力；眼力；远见卓识","g":"[uncountable]","ex":{"en":"She had vision and determination.","cn":"她有远见和决心。"}},{"en":"a person of great beauty or who shows the quality mentioned","cn":"容貌极美的人；有…气质的人","g":"[countable]","lab":"literary","ex":{"en":"She was a vision in white lace.","cn":"她穿着白色蕾丝的衣服美极了。"}},{"en":"the picture on a television or cinema screen","cn":"（电视或影院屏幕的）影像，画面","g":"[uncountable]","ex":{"en":"We apologize for the loss of vision.","cn":"很抱歉没法显示画面。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"想象;展望","en":"Your vision of a future situation or society is what you imagine or hope it would be like, if things were very different from the way they are now.","ex":{"en":"I have a vision of a society that is free of exploitation and injustice","cn":"我希望建立一个没有剥削和不公的社会。"}},{"pos":"N-COUNT 可数名词","cn":"想象;幻想","en":"If you have a vision of someone in a particular situation, you imagine them in that situation, for example because you are worried that it might happen, or hope that it will happen.","ex":{"en":"He had a vision of Cheryl, slumped on a plastic chair in the waiting-room","cn":"他想象谢里尔瘫坐在候诊室的一把塑料椅子上。"}},{"pos":"N-COUNT 可数名词","cn":"幻觉;幻象","en":"A vision is the experience of seeing something that other people cannot see, for example in a religious experience or as a result of madness or taking drugs.","ex":{"en":"It was on 24th June 1981 that young villagers first reported seeing the Virgin Mary in a vision.","cn":"1981年6月24日那天，年轻的村民们首次报告说看到了圣母马利亚的幻象。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"视力;视觉","en":"Your vision is your ability to see clearly with your eyes.","ex":{"en":"It causes blindness or serious loss of vision","cn":"这能导致失明或视力严重受损。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"视野","en":"Your vision is everything that you can see from a particular place or position.","ex":{"en":"Jane blocked Cross's vision and he could see nothing","cn":"简挡住了克罗斯的视线，他什么也看不见。"}}]},"examples":[{"en":"She was a vision in white lace.","cn":"她穿着镶白色网眼纱边的衣服美极了。"},{"en":"He had a vision of a world in which there would be no wars.","cn":"他幻想有一个没有战争的世界。"}]},"vinegar":{"oxford":{"phon":"ˈvɪnɪɡə(r)","pos":"noun","senses":[{"en":"a liquid with a bitter taste made from wine or malt, used to add taste to food or to preserve it","cn":"醋","ex":{"en":"onions pickled in vinegar","cn":"用醋泡制的洋葱"}}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"醋","en":"Vinegar is a sharp-tasting liquid, usually made from sour wine or malt, which is used to make things such as salad dressing."}]},"media":{"uk":"media/uk/vinegar__gb_1.mp3","us":"media/us/vinegar__us_1.mp3","img":["media/ldoce/img/vinegar.jpg"]},"examples":[{"en":"malt/wine vinegar","cn":"麦芽/葡萄酒醋"},{"en":"onions pickled in vinegar","cn":"用醋泡制的洋葱"}]},"viral":{"oxford":{"phon":"ˈvaɪrəl","pos":"adjective","senses":[{"en":"like or caused by a virus","cn":"病毒的；病毒性的；病毒引起的","ex":{"en":"a viral infection","cn":"病毒性感染"}},{"en":"used to describe a piece of information, a video, an image, etc. that is sent rapidly over the internet and seen by large numbers of people within a short time","cn":"（网上信息、视频、图像等）病毒式传播的，快速传播的","ex":{"en":"a viral email","cn":"快速传播的电子邮件"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"病毒性的;病毒引起的","en":"A viral disease or infection is caused by a virus.","ex":{"en":"...a 65-year-old patient suffering from severe viral pneumonia.","cn":"感染了严重病毒性肺炎的65岁病人"}}]},"media":{"uk":"media/uk/viral__gb_1.mp3","us":"media/us/viral__us_1.mp3"},"examples":[{"en":"a viral email (= that is sent on from one person to others, who then send it on again)","cn":"传播病毒邮件"},{"en":"a viral infection","cn":"病毒性感染"}]},"visitor":{"media":{"uk":"media/uk/visitor__gb_1.mp3","us":"media/us/visitor__us_1.mp3"},"oxford":{"phon":"ˈvɪzɪtə(r)","pos":"noun","senses":[{"en":"a person who visits a person or place","cn":"来访者；访问者；参观者；游客","ex":{"en":"We've got visitors coming this weekend.","cn":"本周末我们有客人来访。"}},{"en":"a person who looks at a website on the internet","cn":"（网站的）访客","lab":"computing","ex":{"en":"How can we attract more visitors to our website?","cn":"我们如何才能吸引更多人访问我们的网站呢？"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"访问者;参观者","en":"A visitor is someone who is visiting a person or place.","ex":{"en":"The other day we had some visitors from Switzerland","cn":"前几天我们接待了几位来自瑞士的参观者。"}}]},"examples":[{"en":"How can we attract more visitors to our website?","cn":"我们如何才能吸引更多人访问我们的网站呢？"},{"en":"The theme park attracts 2.5 million visitors a year.","cn":"这个主题乐园每年吸引 250 万游客。"}]},"violence":{"media":{"uk":"media/uk/violence__gb_1.mp3","us":"media/us/violence__us_1.mp3"},"oxford":{"phon":"ˈvaɪələns","pos":"noun","senses":[{"en":"violent behaviour that is intended to hurt or kill somebody","cn":"暴力；暴行","ex":{"en":"Police do not think this killing was a random act of violence.","cn":"警方认为这起杀戮并非随机的暴力行为。"}},{"en":"physical or emotional force and energy","cn":"狂热；激情；激烈的力量","ex":{"en":"The violence of her feelings surprised him.","cn":"她感情之强烈使他吃惊。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"暴力;暴行","en":"Violence is behaviour which is intended to hurt, injure, or kill people.","ex":{"en":"Twenty people were killed in the violence","cn":"有20人在这一暴力事件中丧生。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（言行的）狂暴，激烈，愤怒","en":"If you do or say something with violence, you use a lot of force and energy in doing or saying it, often because you are angry.","ex":{"en":"'There's no need,' Amy said, with sudden violence","cn":"“没有必要，”埃米突然激愤地说。"}}]},"examples":[{"en":"Why do they always have to resort to violence?","cn":"为什么他们总是非要诉诸暴力不可呢？"},{"en":"He condemned the protesters' use of violence against the police.","cn":"他谴责抗议者对警察使用暴力。"}]},"viewing":{"lemma":"view","media":{"uk":"media/uk/view__gb_1.mp3","us":"media/us/view__us_1.mp3"}},"vital":{"media":{"uk":"media/uk/vital__gb_1.mp3","us":"media/us/vital__us_1.mp3"},"oxford":{"phon":"ˈvaɪtl","pos":"adjective","senses":[{"en":"necessary or essential in order for something to succeed or exist","cn":"必不可少的；对…极重要的","ex":{"en":"the vitamins that are vital for health","cn":"保持健康必不可少的维生素"}},{"en":"connected with or necessary for staying alive","cn":"生命的；维持生命所必需的","g":"[only before noun]","ex":{"en":"the vital organs (= the brain, heart, lungs, etc.)","cn":"重要脏器"}},{"en":"full of energy and enthusiasm","cn":"生气勃勃的；充满生机的；热情洋溢的"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"必要的;至关重要的;必不可少的","en":"If you say that something is vital, you mean that it is necessary or very important.","ex":{"en":"The port is vital to supply relief to millions of drought victims","cn":"这个港口对向数百万旱灾灾民提供救援物资是至关重要的。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"充满活力的;生气勃勃的","en":"If you describe someone or something as vital, you mean that they are very energetic and full of life.","ex":{"en":"They are both very vital people and a good match","cn":"他俩都很有活力，十分般配。"}}]},"examples":[{"en":"Good financial accounts are vital to the success of any enterprise.","cn":"妥善的财务账目对任何公司的成功都是极其重要的。"},{"en":"The police play a vital role in our society.","cn":"警察在我们的社会中起着极其重要的作用。"}]},"violations":{"lemma":"violation"},"vibrations":{"lemma":"vibration"},"visit":{"media":{"uk":"media/uk/visit__gb_1.mp3","us":"media/us/visit__us_1.mp3"},"oxford":{"phon":"ˈvɪzɪt","pos":"verb","senses":[{"en":"to go to see a person or a place for a period of time","cn":"访问；拜访；看望；参观","g":"[transitive]","ex":{"en":"My parents are coming to visit me next week.","cn":"我父母下周要来看我。"}},{"en":"to go to a website on the internet","cn":"访问（网站）","g":"[transitive]","lab":"computing","ex":{"en":"For more information, visit our website.","cn":"欲知详情，请访问我们的网站。"}},{"en":"to stay somewhere for a short time","cn":"（短暂地）做客，逗留","g":"[intransitive, transitive]","ex":{"en":"We don't live here. We're just visiting.","cn":"我们不住在这里，只是短期停留。"}},{"en":"to make an official visit to somebody, for example to perform checks or give advice","cn":"视察；巡视","g":"[transitive]","ex":{"en":"Government inspectors are visiting schools in the area.","cn":"政府督学正在巡视这一地区的学校。"}},{"en":"an occasion or a period of time when somebody goes to see a place or person and spends time there","cn":"访问；参观；游览；看望","lab":"British English","ex":{"en":"a two-day/three-day visit","cn":"两日／三日的游览"},"pos":"noun"},{"en":"an occasion when somebody looks at a website on the internet","cn":"（到网站的）访问","lab":"computing","ex":{"en":"Visits to our website have doubled in a year.","cn":"我们网站的访问人次一年内翻了一番。"},"pos":"noun"},{"en":"an occasion when two or more people meet to talk in an informal way","cn":"碰头；会面","lab":"North American English, informal，，","ex":{"en":"He thought back to his visit with the doctor.","cn":"他回想起他当时与医生拉家常的情形。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"看望;拜访","en":"If you visit someone, you go to see them and spend time with them.","ex":{"en":"He wanted to visit his brother in Worcester","cn":"他想去看望住在伍斯特的哥哥。"}},{"pos":"VERB 动词","cn":"访问;参观;游览","en":"If you visit a place, you go there for a short time.","ex":{"en":"He'll be visiting four cities including Cagliari in Sardinia","cn":"他将要访问4个城市，包括萨迪尼亚的卡利亚里。"}},{"pos":"VERB 动词","cn":"访问，浏览（网站）","en":"If you visit a website, you look at it.","ex":{"en":"For details visit our website at www.cobuild.collins.co.uk.","cn":"欲知详情，请访问我们的网站www.cobuild.collins.co.uk。"}},{"pos":"VERB 动词","cn":"上门咨询（专业人士）;（专业人士）上门服务","en":"If you visit a professional person such as a doctor or lawyer, you go and see them in order to get professional advice. If they visit you, they come to see you in order to give you professional advice.","ex":{"en":"If necessary the patient can then visit his doctor for further advice","cn":"如有必要，病人可以上门咨询自己的医生以得到更多的建议。"}},{"pos":"V-PASSIVE 被动动词","cn":"（不快之事）降临在…身上","en":"If something very unpleasant is visited upon you, it happens to you.","ex":{"en":"Violence is visited upon us every day","cn":"暴力事件每天都会降临在我们身上。"}},{"pos":"","cn":"","en":"相关词组：visit with"}]},"examples":[{"en":"Visits to our website have doubled in a year.","cn":"我们网站的访问人次一年内翻了一番。"},{"en":"You should visit your dentist at least twice a year.","cn":"你应该每年至少去看两次牙科医生。"}]},"violent":{"media":{"uk":"media/uk/violent__gb_1.mp3","us":"media/us/violent__us_1.mp3"},"oxford":{"phon":"ˈvaɪələnt","pos":"adjective","senses":[{"en":"involving or caused by physical force that is intended to hurt or kill somebody","cn":"暴力的；强暴的","ex":{"en":"violent crime/criminals","cn":"暴力犯罪／罪犯"}},{"en":"showing or caused by very strong emotion","cn":"感情强烈的；激情的；由激情引起的","ex":{"en":"Toddlers can be prone to violent outbursts.","cn":"幼儿很容易爆发暴力行为。"}},{"en":"very strong and sudden","cn":"猛烈的；剧烈的；强烈的","g":"[usually before noun]","ex":{"en":"I took a violent dislike to him.","cn":"我很讨厌他。"}},{"en":"extremely bright","cn":"强烈的；鲜艳夺目的","g":"[usually before noun]","ex":{"en":"Her dress was a violent pink.","cn":"她的连衣裙是非常鲜艳的粉红色。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"暴力的;粗暴的;凶暴的","en":"If someone is violent, or if they do something which is violent, they use physical force or weapons to hurt, injure, or kill other people.","ex":{"en":"A quarter of current inmates have committed violent crimes.","cn":"现在关押的犯人中有1/4是暴力犯罪。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"剧烈的;猛烈的;强力的","en":"A violent event happens suddenly and with great force.","ex":{"en":"A violent impact hurtled her forward","cn":"一股强大的冲击波把她向前抛去。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（言行或感觉）激烈的，强烈的，狂暴的","en":"If you describe something as violent, you mean that it is said, done, or felt very strongly.","ex":{"en":"Violent opposition to the plan continues","cn":"对该计划的强烈反对之声仍不绝于耳。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（变化）剧烈的，急剧的","en":"Violent changes are extreme changes from one state to another.","ex":{"en":"Larry began suffering severe headaches and violent mood swings.","cn":"拉里开始出现严重的头痛和剧烈的情绪波动。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（死亡）痛苦的，突发性的，暴力造成的","en":"A violent death is painful and unexpected, usually because the person who dies has been murdered.","ex":{"en":"...an innocent man who had met a violent death.","cn":"死于非命的无辜男子"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（电影或电视节目）多暴力镜头的，渲染暴力的","en":"A violent film or television programme contains a lot of scenes which show violence.","ex":{"en":"It was the most violent film that I have ever seen.","cn":"这是我看过的最暴力的一部电影。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（色彩）强烈的，刺目的，鲜艳夺目的","en":"If you describe a colour as violent, you mean that it is extremely, and often unpleasantly, bright.","ex":{"en":"...the violent red of dying sunset.","cn":"夕阳将逝时夺目的红色"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（天气）恶劣的，多风暴的","en":"Violent weather is extremely stormy and windy.","ex":{"en":"A violent storm had struck the area.","cn":"一场猛烈的暴风雨席卷了该地区。"}}]},"examples":[{"en":"Her dress was a violent pink.","cn":"她的连衣裙是非常鲜艳的粉红色。"},{"en":"The crowd suddenly turned violent.","cn":"人群中突然有人开始大打出手。"}]},"violin":{"oxford":{"phon":"ˌvaɪəˈlɪn","pos":"noun","senses":[{"en":"a musical instrument with strings, which you hold under your chin and play with a bow","cn":"小提琴","ex":{"en":"Brahms’ violin concerto","cn":"勃拉姆斯的小提琴协奏曲"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"小提琴","en":"A violin is a musical instrument. Violins are made of wood and have four strings. You play the violin by holding it under your chin and moving a bow across the strings.","ex":{"en":"Lizzie used to play the violin.","cn":"莉齐曾经拉过小提琴。"}}]},"media":{"img":["media/ldoce/img/violin.jpg","media/pic/strings_musicalinstruments_comp.jpg"],"uk":"media/uk/violin__gb_1.mp3","us":"media/us/violin__us_1.mp3"},"examples":[{"en":"Brahms' violin concerto","cn":"勃拉姆斯的小提琴协奏曲"}]},"viruses":{"lemma":"virus"},"virtually":{"media":{"uk":"media/uk/virtually__gb_1.mp3","us":"media/us/virtually__us_1.mp3"},"oxford":{"phon":"ˈvɜːtʃuəli","pos":"adverb","senses":[{"en":"almost or very nearly, so that any slight difference is not important","cn":"几乎；差不多；事实上；实际上","ex":{"en":"to be virtually impossible","cn":"几乎不可能"}},{"en":"by the use of computer software that makes something appear to exist; using virtual reality technology","cn":"模拟；虚拟；以模拟现实技术","lab":"computing"}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"几乎;实际上;事实上;差不多","en":"You can use virtually to indicate that something is so nearly true that for most purposes it can be regarded as true.","ex":{"en":"Virtually all cooking was done over coal-fired ranges","cn":"差不多所有的烹饪都是在燃煤灶上进行的。"}}]},"examples":[{"en":"Virtually all students will be exempt from the tax.","cn":"差不多所有的学生都会获得豁免此税项。"},{"en":"This year's results are virtually the same as last year's.","cn":"今年的结果几乎和去年的一样。"}]},"vibration":{"oxford":{"phon":"vaɪˈbreɪʃn","pos":"noun","senses":[{"en":"a continuous shaking movement or feeling","cn":"震动；颤动；抖动；（感情的）共鸣","g":"[countable, uncountable]","ex":{"en":"We could feel the vibrations from the trucks passing outside.","cn":"我们可以感到外面卡车经过时的颤动。"}},{"en":"a mood or an atmosphere produced by a particular person, thing or place","cn":"情绪；气氛；氛围","g":"[plural]","lab":"formal"}]},"media":{"uk":"media/uk/vibration__gb_1.mp3","us":"media/us/vibration__us_1.mp3"},"examples":[{"en":"We could feel the vibrations from the trucks passing outside.","cn":"我们可以感到外面卡车经过时的颤动。"},{"en":"a reduction in the level of vibration in the engine","cn":"发动机震动程度的下降"}]},"vivid":{"media":{"uk":"media/uk/vivid__gb_1.mp3","us":"media/us/vivid__us_1.mp3"},"oxford":{"phon":"ˈvɪvɪd","pos":"adjective","senses":[{"en":"producing very clear pictures in your mind","cn":"清晰的；生动的；逼真的","ex":{"en":"vivid memories","cn":"清晰的记忆"}},{"en":"very bright","cn":"鲜明的；耀眼的；鲜艳的；强烈的","ex":{"en":"vivid blue eyes","cn":"碧蓝的眼睛"}},{"en":"able to form pictures of ideas, situations, etc. easily in the mind","cn":"丰富的","ex":{"en":"a wonderfully vivid imagination","cn":"生动逼真的想象"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（记忆、描述等）生动的,逼真的,清晰的","en":"If you describe memories and descriptions as vivid, you mean that they are very clear and detailed.","ex":{"en":"People of my generation who lived through World War II have vivid memories of confusion and incompetence","cn":"我们这一代经历过二战的人都真切地记得当时的迷惘和无助。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（色彩）明亮的,鲜艳的","en":"Something that is vivid is very bright in colour.","ex":{"en":"...a vivid blue sky.","cn":"蔚蓝的天空"}}]},"examples":[{"en":"He gave a vivid account of his life as a fighter pilot.","cn":"他生动地描述了他那战斗机飞行员的生活。"},{"en":"I vividly remember the day we first met.","cn":"我对我们第一次相见的那天记忆犹新。"}]},"videotape":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"录像带;录影带","en":"Videotape is magnetic tape that is used to record moving pictures and sounds to be shown on television."},{"pos":"N-COUNT 可数名词","cn":"同video cassette","en":"A videotape is the same as a video cassette ."},{"pos":"VERB 动词","cn":"把…录在录像带上","en":"If you videotape a television programme or event, you record it on tape using a video recorder or video camera, so that you can watch it later.","ex":{"en":"She videotaped the entire trip.","cn":"她录下了整个行程。"}}]},"media":{"uk":"media/uk/videotape__gb_1.mp3","us":"media/us/videotape__us_1.mp3"},"examples":[{"en":"a videotaped interview","cn":"录像访谈"},{"en":"a videotape of everyday life in Havana","cn":"记录哈瓦那日常生活的录像带"}],"oxford":{"phon":"ˈvɪdiəʊteɪp","pos":"noun","senses":[{"en":"a type of magnetic tape used in the past for recording moving pictures and sound; a box containing this tape, also called a video cassette","cn":"录像带；盒式录像带","ex":{"en":"Film can also be copied onto videotape.","cn":"电影同样可以复制到录像带上。"}},{"en":"to record a television programme using a video cassette recorder","cn":"录电视节目；给…录像","ex":{"en":"a videotaped interview","cn":"录像访谈"},"pos":"verb"}]}},"visual":{"media":{"uk":"media/uk/visual__gb_1.mp3","us":"media/us/visual__us_1.mp3"},"oxford":{"phon":"ˈvɪʒuəl","pos":"adjective","senses":[{"en":"of or connected with seeing or sight","cn":"视力的；视觉的","ex":{"en":"the visual arts","cn":"视觉艺术"}},{"en":"a picture, map, piece of film, etc. used to make an article or a talk easier to understand or more interesting","cn":"视觉资料（指说明性的图片、影片等）","ex":{"en":"He used striking visuals to get his point across.","cn":"他用醒目的视觉资料解释他的观点。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"视觉的;视力的;可见的","en":"Visual means relating to sight, or to things that you can see.","ex":{"en":"...the graphic visual depiction of violence.","cn":"对暴力赤裸裸的影像描绘"}},{"pos":"N-COUNT 可数名词","cn":"视觉材料（指用于展示或说明的图画、表格、影片等）","en":"A visual is something such as a picture, diagram, or piece of film that is used to show or explain something.","ex":{"en":"Remember you want your visuals to reinforce your message, not detract from what you are saying.","cn":"要记住，使用视觉材料是为了使表达的意思更加清楚明白，而不能分散对所讲内容的注意力。"}}]},"examples":[{"en":"The building makes a tremendous visual impact.","cn":"这栋建筑物给人以极其深刻的视觉印象。"},{"en":"He used striking visuals to get his point across.","cn":"他用醒目的视觉资料解释他的观点。"}]},"victory":{"oxford":{"phon":"ˈvɪktəri","pos":"noun","senses":[{"en":"success in a game, an election, a war, etc.","cn":"胜利；成功","ex":{"en":"to win a narrow victory","cn":"险胜"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"获胜;战胜;胜利","en":"A victory is a success in a struggle, war, or competition.","ex":{"en":"Union leaders are heading for victory in their battle over workplace rights.","cn":"工会领袖们即将赢得争取工作场所权利斗争的胜利。"}},{"pos":"PHRASE 短语","cn":"精神胜利","en":"If you say that someone has won a moral victory, you mean that although they have officially lost a contest or dispute, they have succeeded in showing they are right about something.","ex":{"en":"She said her party had won a moral victory","cn":"她说她的党派虽败犹荣。"}}]},"media":{"uk":"media/uk/victory__gb_1.mp3","us":"media/us/victory__us_1.mp3"},"examples":[{"en":"She is confident of victory in Saturday's final.","cn":"她对在星期六决赛中取得胜利充满信心。"},{"en":"He swept to victory in the final of the championship.","cn":"他在锦标赛的决赛中轻而易举地获胜。"}]},"via":{"media":{"uk":"media/uk/via__gb_1.mp3","us":"media/us/via__us_1.mp3"},"oxford":{"phon":"ˈvaɪə","pos":"preposition","senses":[{"en":"through a place","cn":"经由，经过（某一地方）","ex":{"en":"We flew home via Dubai.","cn":"我们乘飞机经迪拜回国。"}},{"en":"by means of a particular person, system, etc.","cn":"通过，凭借（某人、系统等）","ex":{"en":"I heard about the sale via Jane.","cn":"我从简那里听说了这次大减价。"}}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"经由;经过","en":"If you go somewhere via a particular place, you go through that place on the way to your destination.","ex":{"en":"We drove via Lovech to the old Danube town of Ruse","cn":"我们开车经由洛维奇到达了多瑙河畔的古镇鲁塞。"}},{"pos":"PREP 介词","cn":"通过;凭借;靠","en":"If you do something via a particular means or person, you do it by making use of that means or person.","ex":{"en":"The technology to allow relief workers to contact the outside world via satellite already exists","cn":"能够让救援人员通过卫星与外界联系的技术已经存在。"}}]},"examples":[{"en":"The news programme came to us via satellite.","cn":"新闻节目是通过卫星传送到我们这里来的。"},{"en":"I heard about the sale via Jane.","cn":"我从简那里听说了这次大减价。"}]},"video":{"media":{"uk":"media/uk/video__gb_1.mp3","us":"media/us/video__us_1.mp3"},"oxford":{"phon":"ˈvɪdiəʊ","pos":"noun","senses":[{"en":"a system of recording moving pictures and sound, either using a digital method of storing data or (in the past) using videotape","cn":"录像系统","g":"[uncountable]","ex":{"en":"A wedding is the perfect subject for video.","cn":"婚礼是极好的录像主题。"}},{"en":"a short film or recording of an event, made using digital technology and viewed on a computer, especially over the internet","cn":"视频；视频剪辑","g":"[countable, uncountable]","ex":{"en":"The school made a short promotional video.","cn":"学校录制了一条宣传短片。"}},{"en":"a short film made by a pop or rock band to be shown with a song when it is played on television or online","cn":"音乐短片","g":"[countable]","ex":{"en":"The group's new video will be released next month.","cn":"这个音乐组合的新录像将在下个月发行。"}},{"en":"a type of magnetic tape used in the past for recording moving pictures and sound; a box containing this tape, also called a video cassette","cn":"录像带；盒式录像带","g":"[uncountable, countable]","ex":{"en":"The movie was released on video later that year.","cn":"该电影于当年晚些时候以视频形式发行。"}},{"en":"a copy of a film, programme, etc. recorded on videotape","cn":"（指制品）录像，录影","g":"[countable]","lab":"British English","ex":{"en":"We used to rent videos nearly every weekend.","cn":"我们过去几乎每个周末都会租用视频。"}},{"en":"a piece of equipment used, especially in the past, to record and play films and TV programmes on video","cn":"录像机","g":"[countable]","lab":"British English","ex":{"en":"I never even learned to programme the video.","cn":"我什至从未学会过对视频进行编程。"}},{"en":"to record moving pictures and sound, either using a digital method of storing data or (in the past) using videotape","cn":"录视频；给…录像","ex":{"en":"Videoing students can be a useful teaching exercise.","cn":"给学生录像可以成为有用的教学活动。"},"pos":"verb"},{"en":"to record a television programme using a vcr (= video cassette recorder)","cn":"录电视节目；给…录像","lab":"formal","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"录像节目","en":"A video is a film or television programme recorded on tape for people to watch on a television set.","ex":{"en":"We were watching videos with her.","cn":"我们当时在和她一起看录像。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"录像;录影","en":"Video is the system of recording films and events on tape so that people can watch them on a television set.","ex":{"en":"She has watched the race on video.","cn":"她看了比赛的录像。"}},{"pos":"N-COUNT 可数名词","cn":"录像机","en":"A video is a machine that you can use to record television programmes and play videotapes on a television set.","ex":{"en":"He'd set the video for 8.00.","cn":"他把录像机的时间设在8点钟。"}},{"pos":"VERB 动词","cn":"录制;制作…的录像","en":"If you video a television programme or event, you record it on tape using a video recorder or video camera, so that you can watch it later.","ex":{"en":"She had been videoing the highlights of the tournament","cn":"她一直在制作锦标赛集锦的录像。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"视频播放软件","en":"Video is a system by which you can see television images or films on your computer, rather than on a television set."}]},"examples":[{"en":"Upload your videos and share them with friends and family online.","cn":"上传你的视频，与朋友和家人在线分享。"},{"en":"Videoing students can be a useful teaching exercise.","cn":"给学生录像可以成为有用的教学活动。"}]},"vicinity":{"media":{"uk":"media/uk/vicinity__gb_1.mp3","us":"media/us/vicinity__us_1.mp3"},"oxford":{"phon":"vəˈsɪnəti","pos":"noun","senses":[{"en":"the area around a particular place","cn":"周围地区；邻近地区；附近","ex":{"en":"Crowds gathered in the vicinity of Trafalgar Square.","cn":"成群结队的人聚集在特拉法尔加广场周围。"}}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"邻近地区;附近","en":"If something is in the vicinity of a particular place, it is near it.","ex":{"en":"There were a hundred or so hotels in the vicinity of the railway station","cn":"在火车站附近大约有100家旅馆。"}}]},"examples":[{"en":"Crowds gathered in the vicinity of Trafalgar Square.","cn":"成群结队的人聚集在特拉法尔加广场周围。"},{"en":"There is no hospital in the immediate vicinity.","cn":"附近没有医院。"}]},"virtue":{"media":{"uk":"media/uk/virtue__gb_1.mp3","us":"media/us/virtue__us_1.mp3"},"oxford":{"phon":"ˈvɜːtʃuː","pos":"noun","senses":[{"en":"behaviour or attitudes that show high moral standards","cn":"高尚的道德；正直的品性；德行","g":"[uncountable]","lab":"formal","ex":{"en":"He led a life of virtue.","cn":"他过着高尚的生活。"}},{"en":"a particular good quality or habit","cn":"美德；优秀品质；良好习惯","g":"[countable]","ex":{"en":"Patience is not one of her virtues, I'm afraid.","cn":"恐怕她没有耐心。"}},{"en":"an attractive or useful quality","cn":"优点；长处；用处","g":"[countable, uncountable]","ex":{"en":"The plan has the virtue of simplicity.","cn":"这项计划的优点是简单。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"善行;正直的品性;良好的习惯","en":"Virtue is thinking and doing what is right and avoiding what is wrong.","ex":{"en":"Virtue is not confined to the Christian world","cn":"善行并不是仅限于基督教世界。"}},{"pos":"N-COUNT 可数名词","cn":"美德;德行","en":"A virtue is a good quality or way of behaving.","ex":{"en":"His virtue is patience","cn":"耐心是他的美德。"}},{"pos":"N-COUNT 可数名词","cn":"优点;长处","en":"The virtue of something is an advantage or benefit that it has, especially in comparison with something else.","ex":{"en":"There was no virtue in returning to Calvi the way I had come","cn":"沿着我来的路线返回卡尔维并不可取。"}},{"pos":"PREP-PHRASE 短语介词","cn":"靠;凭借;由于;因为","en":"You use by virtue of to explain why something happens or is true.","ex":{"en":"The article stuck in my mind by virtue of one detail","cn":"由于一个细节，这篇文章在我脑海里印象深刻。"}},{"pos":"PHRASE 短语","cn":"（假装）心甘情愿地做（迫不得已的事）","en":"If you make a virtue of something, you pretend that you did it because you chose to, although in fact you did it because you had to.","ex":{"en":"The movie makes a virtue out of its economy.","cn":"这部电影充分利用了其有限的成本。"}}]},"examples":[{"en":"She got the job by virtue of her greater experience.","cn":"她由于经验较为丰富而得到了那份工作。"},{"en":"They could see no virtue in discussing it further.","cn":"他们看不到再讨论下去有什么用处。"}]},"videos":{"lemma":"video","media":{"uk":"media/uk/video__gb_1.mp3","us":"media/us/video__us_1.mp3"}},"violently":{"oxford":{"phon":"ˈvaɪələntli","pos":"adverb","senses":[{"en":"with great energy or strong movement, especially caused by a strong emotion such as fear or hate","cn":"强烈地；激烈地","ex":{"en":"She shook her head violently.","cn":"她拼命摇头。"}},{"en":"very strongly or severely","cn":"猛烈地；厉害地","ex":{"en":"He was violently sick.","cn":"他病得很厉害。"}},{"en":"in a way that involves physical violence","cn":"凶猛地；凶狠地；强烈地","ex":{"en":"The crowd reacted violently.","cn":"人群反应强烈。"}}]},"media":{"uk":"media/uk/violently__gb_1.mp3","us":"media/us/violently__us_1.mp3"},"examples":[{"en":"They are violently opposed to the idea.","cn":"他们强烈反对这个想法。"},{"en":"He was violently sick.","cn":"他病得很厉害。"}]},"viceroy":{"media":{"uk":"media/uk/viceroy__gb_1.mp3","us":"media/us/viceroy__us_1.mp3"},"oxford":{"phon":"ˈvaɪsrɔɪ","pos":"noun","senses":[{"en":"(in the past) a person who was sent by a king or queen to govern a colony","cn":"（旧时受君主委派管治殖民地的）总督"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（旧时代表国王、女王或政府统治殖民地的）总督","en":"In former times, a viceroy was the person who ruled a colony on behalf of his king, queen, or government."}]},"examples":[{"en":"the viceroy of India","cn":"印度总督"}]},"virus":{"oxford":{"phon":"ˈvaɪrəs","pos":"noun","senses":[{"en":"a living thing, too small to be seen without a microscope, that causes disease in people, animals and plants","cn":"病毒；滤过性病毒","lab":"British English","ex":{"en":"the flu/influenza virus","cn":"流感病毒"}},{"en":"a disease caused by a virus","cn":"病毒性疾病；病毒病","lab":"informal","ex":{"en":"There's a virus going around the office.","cn":"办公室里流行着一种病毒性疾病。"}},{"en":"instructions that are hidden within a computer program and are designed to cause faults or destroy data","cn":"（计算机程序中的）病毒","ex":{"en":"a computer virus","cn":"计算机病毒"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"病毒","en":"A virus is a kind of germ that can cause disease.","ex":{"en":"There are many different strains of flu virus.","cn":"流感病毒有很多不同类型。"}},{"pos":"N-COUNT 可数名词","cn":"病毒","en":"In computer technology, a virus is a program that introduces itself into a system, altering or destroying the information stored in the system.","ex":{"en":"Hackers are said to have started a computer virus.","cn":"据说黑客们已经开始传播一种新的电脑病毒。"}}]},"media":{"uk":"media/uk/virus__gb_1.mp3","us":"media/us/virus__us_1.mp3"},"examples":[{"en":"There's a virus going around the office.","cn":"办公室里流行着一种病毒性疾病。"},{"en":"the flu virus","cn":"流感病毒"}]},"visually":{"oxford":{"phon":"ˈvɪʒuəli","pos":"adverb","senses":[{"en":"in a way that is connected with seeing or sight","cn":"视力的；视觉的","ex":{"en":"visually impaired","cn":"视力障碍"}}]},"media":{"uk":"media/uk/visually__gb_1.mp3","us":"media/us/visually__us_1.mp3"},"examples":[{"en":"visually handicapped/impaired","cn":"有视力障碍的；视力受损的"},{"en":"visually exciting","cn":"视觉上令人兴奋"}]},"view":{"media":{"uk":"media/uk/view__gb_1.mp3","us":"media/us/view__us_1.mp3","img":["media/ldoce/img/view.jpg"]},"oxford":{"phon":"vjuː","pos":"noun","senses":[{"en":"what you can see from a particular place or position, especially beautiful countryside","cn":"（从某处看到的）景色，风景；（尤指）乡间美景","g":"[countable]","sc":"what you can see","ex":{"en":"There were magnificent views of the surrounding countryside.","cn":"四周乡间的景色壮观秀丽。"}},{"en":"used when you are talking about whether you can see something or whether something can be seen in a particular situation","cn":"观看；看；视野；视线","g":"[uncountable, singular]","sc":"what you can see","ex":{"en":"The lake soon came into view.","cn":"那片湖很快映入眼帘。"}},{"en":"a personal opinion about something; an attitude towards something","cn":"（个人的）看法，意见，见解；态度","g":"[countable]","sc":"opinion","ex":{"en":"to have strong political views","cn":"持强硬的政治观点"}},{"en":"a way of understanding or thinking about something","cn":"（理解或思维的）方法，方式","g":"[singular]","sc":"way of understanding","ex":{"en":"He has an optimistic view of life.","cn":"他乐观地看待人生。"}},{"en":"an occasion when a video is watched online","cn":"（线上视频的）观看，播放","g":"[countable]","sc":"online","ex":{"en":"His performance went viral, attracting over 8 million views on YouTube.","cn":"他的表演火了，在 YouTube 视频网站吸引了超过 800 万人次的观看。"}},{"en":"a photograph or picture that shows an interesting place or scene","cn":"风景照；风景画","g":"[countable]","sc":"photograph/picture","ex":{"en":"a book with views of Paris","cn":"一本巴黎风光画册"}},{"en":"a special chance to see or admire something","cn":"（一次）观看；一睹；一览","g":"[countable]","sc":"chance to see something"},{"en":"to think about somebody/something in a particular way","cn":"把…视为；以…看待","sc":"think about something","ex":{"en":"How do you view your position within the company?","cn":"你如何看待自己在公司中的位置？"},"pos":"verb"},{"en":"to look at something, especially when you look carefully","cn":"看；观看；（尤指）仔细察看","lab":"formal","sc":"look at something","ex":{"en":"People came from all over the world to view her work.","cn":"人们从世界各地涌来欣赏她的作品。"},"pos":"verb"},{"en":"to visit a house, etc. before deciding whether to buy or rent it","cn":"查看，察看（房子等，以决定是否购买或租用）","lab":"formal","sc":"look at something","ex":{"en":"The property can only be viewed by appointment.","cn":"察看这处房产须预约。"},"pos":"verb"},{"en":"to watch television, a film, etc.","cn":"看，观看（电视、电影等）","lab":"formal","sc":"watch TV, film/movie","ex":{"en":"The show has a viewing audience of six million (= six million people watch it).","cn":"这个节目有六百万观众观看。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"观点;看法;见解;态度","en":"Your views on something are the beliefs or opinions that you have about it, for example whether you think it is good, bad, right, or wrong.","ex":{"en":"Washington and Moscow are believed to have similar views on Kashmir","cn":"据信华盛顿和莫斯科在克什米尔问题上的看法相似。"}},{"pos":"N-SING 单数名词","cn":"（对某一问题的）看法，考虑，思量","en":"Your view of a particular subject is the way that you understand and think about it.","ex":{"en":"The drama takes an idealistic, even a naive view of the subject","cn":"这部戏在对待这一主题上有些理想化，甚至是天真。"}},{"pos":"VERB 动词","cn":"考虑;看待","en":"If you view something in a particular way, you think of it in that way.","ex":{"en":"First-generation Americans view the United States as a land of golden opportunity","cn":"第一代美国人认为美国是一个充满了机遇的国度。"}},{"pos":"N-COUNT 可数名词","cn":"景观;景色;风景;(尤指）美景","en":"The view from a window or high place is everything which can be seen from that place, especially when it is considered to be beautiful.","ex":{"en":"The view from our window was one of beautiful green countryside","cn":"从我们的窗口能看见一片美丽的绿色田园风光。"}},{"pos":"N-SING 单数名词","cn":"视线;视域;视野","en":"If you have a view of something, you can see it.","ex":{"en":"He stood up to get a better view of the blackboard","cn":"为了更清楚地看到黑板上的内容，他站了起来。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"在能看得见的地方/在（所有人）视线内","en":"You use view in expressions to do with being able to see something. For example, if something is in view, you can see it. If something is in full view of everyone, everyone can see it.","ex":{"en":"She was lying there in full view of anyone who walked by","cn":"她躺在那里，过往的人都能看见她。"}},{"pos":"VERB 动词","cn":"查看;察看","en":"If you view something, you look at it for a particular purpose.","ex":{"en":"They came back to view the house again","cn":"他们又回来查看了一遍房子。"}},{"pos":"VERB 动词","cn":"看;收看","en":"If you view a television programme, video, or film, you watch it.","ex":{"en":"We have viewed the video recording of the incident","cn":"我们看过了该事件的录像。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（文本或图表在计算机屏幕上的）显示方式","en":"View refers to the way in which a piece of text or graphics is displayed on a computer screen.","ex":{"en":"To see the current document in full-page view, click the Page Zoom Full button.","cn":"要完整显示当前文件，请按“全屏显示”按钮。PRHASES"}},{"pos":"PHRASE 短语","cn":"对…评价不高;对…持否定看法","en":"If you take a dim view or a poor view of someone or something, you disapprove of them or have a low opinion of them.","ex":{"en":"They took a dim view of local trade unionists","cn":"他们对当地的工会会员们评价很低。"}},{"pos":"PHRASE 短语","cn":"在我看来;按我的看法","en":"You use in my view when you want to indicate that you are stating a personal opinion, which other people might not agree with.","ex":{"en":"In my view things won't change","cn":"依我看，事情不会改变。"}},{"pos":"PREP-PHRASE 短语介词","cn":"鉴于;由于;考虑到","en":"You use in view of when you are taking into consideration facts that have just been mentioned or are just about to be mentioned.","ex":{"en":"In view of the fact that Hobson was not a trained economist his achievements were remarkable","cn":"考虑到霍布森不是科班出身的经济学家，他可谓是成就非凡。"}},{"pos":"PHRASE 短语","cn":"将…作为目标","en":"If you have something in view, you are aware of it and your actions are aimed towards it.","ex":{"en":"They have very clear career aims in view","cn":"他们有非常明确的职业目标。"}},{"pos":"PHRASE 短语","cn":"从长远来看;作长远打算","en":"If you take the long view, you consider what is likely to happen in the future over a long period, rather than thinking only about things that are going to happen soon.","ex":{"en":"Some investors are taking the long view","cn":"一些投资者是从长远角度考虑的。"}},{"pos":"PHRASE 短语","cn":"在展出;陈列着","en":"If something such as a work of art is on view, it is shown in public for people to look at.","ex":{"en":"A significant exhibition of contemporary sculpture will be on view at the Portland Gallery.","cn":"一场关于当代雕塑的重要展览即将在波特兰美术馆开展。"}},{"pos":"PHRASE 短语","cn":"为了;以便","en":"If you do something with a view to doing something else, you do it because you hope it will result in that other thing being done.","ex":{"en":"He has called a meeting of all parties tomorrow, with a view to forming a national reconciliation government.","cn":"为了组建一个协调各方利益的全国性联合政府，他已召集所有党派参加明天的会议。"}}]},"examples":[{"en":"This evidence supports the view that there is too much violence on television.","cn":"这一证据证实了人们认为电视节目中有太多暴力的看法。"},{"en":"A viewing platform gave stunning views over the valley.","cn":"从观景台向山谷望去，景色之壮观令人叹为观止。"}]},"violinist":{"media":{"uk":"media/uk/violinist__gb_1.mp3","us":"media/us/violinist__us_1.mp3"},"oxford":{"phon":"ˌvaɪəˈlɪnɪst","pos":"noun","senses":[{"en":"a person who plays the violin","cn":"小提琴手；小提琴演奏者"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"小提琴演奏者;小提琴手","en":"A violinist is someone who plays the violin."}]}},"vigorously":{"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"in a way that uses a lot of energy and strength or determination","cn":"强度大地；积极地"}]},"examples":[{"en":"She campaigned vigorously for women’s rights.","cn":"她为妇女权利积极奔走。","src":"ld"},{"en":"Bailey vigorously denied the accusations.","cn":"贝利极力否认各项指控。","src":"ld"}],"media":{"uk":"media/uk/vigorously__gb_1.mp3","us":"media/us/vigorously__us_1.mp3"},"oxford":{"phon":"ˈvɪɡərəsli","pos":"adverb","senses":[{"en":"in a way that is very active, determined or full of energy","cn":"充满活力的；果断的；精力充沛的","ex":{"en":"She shook her head vigorously.","cn":"她拼命地摇头。"}}]}},"vine":{"media":{"uk":"media/uk/vine__gb_1.mp3","us":"media/us/vine__us_1.mp3"},"oxford":{"phon":"vaɪn","pos":"noun","senses":[{"en":"a climbing plant that produces grapes","cn":"葡萄藤","ex":{"en":"grapes on the vine","cn":"藤上的葡萄"}},{"en":"any climbing plant with long, thin stems; one of these stems","cn":"藤本植物；攀缘植物；藤；藤蔓"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"藤本植物;攀援植物;（尤指）葡萄藤","en":"A vine is a plant that grows up or over things, especially one which produces grapes.","ex":{"en":"Every square metre of soil was used, mainly for olives, vines, and almonds.","cn":"每一寸土地都利用上了，主要用来种植橄榄树、葡萄藤和杏树。"}}]},"examples":[{"en":"grapes on the vine","cn":"藤上的葡萄"},{"en":"vine leaves","cn":"葡萄叶"}]},"viking":{"media":{"uk":"media/uk/viking__gb_1.mp3","us":"media/us/viking__us_1.mp3"},"oxford":{"phon":"ˈvaɪkɪŋ","pos":"noun","senses":[{"en":"a member of a Scandinavian people who attacked and sometimes settled in parts of north-west Europe, including Britain, in the 8th to the 11th centuries","cn":"北欧海盗，维京人（8到11世纪驾船劫掠北欧和西欧海岸的斯堪的纳维亚人）"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（8至11世纪的）北欧海盗","en":"The Vikings were men who sailed from Scandinavia and attacked villages in most parts of north-western Europe from the 8th to the 11th centuries."}]}},"vice":{"media":{"img":["media/ldoce/img/vice.jpg","media/pic/tools_diy_comp.jpg"],"uk":"media/uk/vice__gb_1.mp3","us":"media/us/vice__us_1.mp3"},"oxford":{"phon":"vaɪs","pos":"noun","senses":[{"en":"criminal activities that involve sex or drugs","cn":"（与性或毒品有关的）罪行","g":"[uncountable]","ex":{"en":"At the door were two plain-clothes detectives from the vice squad.","cn":"门口是两个扫黄缉毒队的便衣侦探。"}},{"en":"behaviour that is evil or immoral; a quality in somebody’s character that is evil or immoral","cn":"恶行；不道德行为；堕落；邪恶","g":"[uncountable, countable]","lab":"humorous","ex":{"en":"The film ended most satisfactorily: vice punished and virtue rewarded.","cn":"这部电影有个令人满意的结局：邪恶受到惩治，美德得到报偿。"}},{"en":"a tool with two metal blocks that can be moved together by turning a screw. The vice is used to hold an object in place while work is done on it.","cn":"台钳；虎钳","g":"[countable]","lab":"especially British English","ex":{"en":"He held my arm in a vice-like (= very firm) grip.","cn":"他的手像虎钳一样紧紧抓住了我的手臂。"}},{"en":"next in rank to somebody and able to represent them or act for them","cn":"副；代理","ex":{"en":"vice-captain","cn":"副舰长"},"pos":"combining form"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"缺点;瑕疵;弱点","en":"A vice is a habit which is regarded as a weakness in someone's character, but not usually as a serious fault.","ex":{"en":"His only vice is to get drunk on champagne after concluding a successful piece of business","cn":"他唯一的缺点就是在成功做成一笔生意后会大喝香槟而醉。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（尤指与色情业、卖淫行为相关的）犯罪活动,恶行","en":"Vice refers to criminal activities, especially those connected with pornography or prostitution.","ex":{"en":"He said those responsible for offences connected with vice, gaming and drugs should be deported on conviction.","cn":"他说，那些被指控与卖淫、赌博和吸毒有关的人一旦罪名成立就应该被驱逐出境。"}},{"pos":"N-COUNT 可数名词","cn":"老虎钳;台钳","en":"A vice is a tool with a pair of parts that hold an object tightly while you do work on it."}]},"examples":[{"en":"The film ended most satisfactorily: vice punished and virtue rewarded.","cn":"这部电影的结尾皆大欢喜：邪恶受到惩治，美德得到报偿。"},{"en":"He held my arm in a vice-like (= very firm) grip.","cn":"他的手像虎钳一样紧紧抓住了我的手臂。"}]},"visible":{"media":{"uk":"media/uk/visible__gb_1.mp3","us":"media/us/visible__us_1.mp3"},"oxford":{"phon":"ˈvɪzəbl","pos":"adjective","senses":[{"en":"that can be seen","cn":"看得见的；可见的","ex":{"en":"The house is clearly visible from the beach.","cn":"从海滩可以清楚地看到那所房子。"}},{"en":"that is obvious enough to be noticed","cn":"明显的；能注意到的","g":"[usually before noun]","ex":{"en":"We have not noticed any visible benefits from the new system.","cn":"我们没有注意到新系统有任何明显的好处。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"可见的;看得见的","en":"If something is visible, it can be seen.","ex":{"en":"The warning lights were clearly visible","cn":"警示信号灯清晰可见。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"明显的;引人注目的;能认出的","en":"You use visible to describe something or someone that people notice or recognize.","ex":{"en":"The most visible sign of the intensity of the crisis is unemployment","cn":"预示危机严重程度的一个最显著的迹象就是失业情况。"}},{"pos":"ADJ 形容词","cn":"有形的;商品的","en":"In economics, visible earnings are the money that a country makes as a result of producing goods, rather than from services such as banking and tourism.","ex":{"en":"In the UK visible imports have traditionally been greater than visible exports.","cn":"在英国，传统上有形产品的进口一直大于出口。"}}]},"examples":[{"en":"The house is clearly visible from the beach.","cn":"从海滩可以清楚地看到那所房子。"},{"en":"She made a visible effort to control her anger.","cn":"看得出她竭力控制自己不发火。"}]},"visiting":{"media":{"uk":"media/uk/visiting__gb_1.mp3","us":"media/us/visiting__us_1.mp3"},"oxford":{"phon":"ˈvɪzɪtɪŋ","pos":"adjective","senses":[{"en":"a visiting professor or lecturer is one who is teaching for a fixed period at a particular university or college, but who normally teaches at another one","cn":"（指教授或讲师）客座的"}]},"base":"visit"},"victim":{"media":{"uk":"media/uk/victim__gb_1.mp3","us":"media/us/victim__us_1.mp3"},"oxford":{"phon":"ˈvɪktɪm","pos":"noun","senses":[{"en":"a person who has been attacked, injured or killed as the result of a crime, a disease, an accident, etc.","cn":"受害者；罹难者；罹病者；牺牲品","ex":{"en":"shooting/murder victims","cn":"枪击/谋杀受害者"}},{"en":"a person who has been tricked","cn":"受骗者；上当的人","ex":{"en":"They were the victims of a cruel hoax.","cn":"他们成了一大骗局的上当受骗者。"}},{"en":"a person or thing that is badly affected by a situation, a decision, etc.","cn":"受到严重影响的人（或事物）；牺牲品；受害者","ex":{"en":"Schools are the latest victims of cuts in public spending.","cn":"学校是削减公共开支的最新的牺牲品。"}},{"en":"an animal or a person that is killed and offered as a sacrifice","cn":"为祭祀杀死的动物（或人）；祭品；牺牲","ex":{"en":"a sacrificial victim","cn":"祭品"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"受害者;遇害者;遇难者","en":"A victim is someone who has been hurt or killed.","ex":{"en":"Not all the victims survived","cn":"并非所有受害者都得以幸存。"}},{"pos":"N-COUNT 可数名词","cn":"（他人行为、信仰或恶劣环境的）牺牲品，受害者","en":"A victim is someone who has suffered as a result of someone else's actions or beliefs, or as a result of unpleasant circumstances.","ex":{"en":"He was a victim of racial prejudice","cn":"他是种族歧视的受害者。"}},{"pos":"PHRASE 短语","cn":"成为…的牺牲品（或受害者)","en":"If you fall victim to something or someone, you suffer as a result of them, or you are killed by them.","ex":{"en":"In the early 1960s, Blyton fell victim to Alzheimer's disease","cn":"在19世纪60年代早期，布莱顿患上了老年痴呆症。"}}]},"examples":[{"en":"Schools are the latest victims of cuts in public spending.","cn":"学校是削减公共开支的最新的牺牲品。"},{"en":"They were the victims of a cruel hoax.","cn":"他们成了一大骗局的上当受骗者。"}]},"villa":{"media":{"uk":"media/uk/villa__gb_1.mp3","us":"media/us/villa__us_1.mp3"},"oxford":{"phon":"ˈvɪlə","pos":"noun","senses":[{"en":"a house where people stay on holiday, especially in southern Europe","cn":"（尤指南欧的）度假别墅","lab":"British English","ex":{"en":"We rented a holiday villa in Spain.","cn":"我们在西班牙租了一座假日别墅。"}},{"en":"a house in the country with a large garden, especially in southern Europe","cn":"（尤指南欧的）乡间庄园"},{"en":"a large house in a town","cn":"（城内的）豪宅","lab":"British English","ex":{"en":"a Victorian villa in North London","cn":"伦敦北部的维多利亚式豪宅"}},{"en":"a country house or farm with land attached to it","cn":"（附有土地的）乡间宅第，别墅，庄园","ex":{"en":"They found the remains of an impressive Roman villa.","cn":"他们发现了一个古罗马大庄园的遗址。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（尤指地中海国家的）度假别墅，乡间别墅","en":"A villa is a fairly large house, especially one that is used for holidays in Mediterranean countries.","ex":{"en":"He lives in a secluded five-bedroom luxury villa.","cn":"他住在一个位置偏远、有5个卧室的豪华乡间别墅里。"}}]},"examples":[{"en":"We rented a holiday villa in Spain.","cn":"我们在西班牙租了一座假日别墅。"},{"en":"a Victorian villa in North London","cn":"伦敦北部的维多利亚式豪宅"}]},"viols":{"oxford":{"phon":"ˈvaɪəl","pos":"noun","senses":[{"en":"an early type of musical instrument with strings, shaped like a violin","cn":"维奥尔琴（一种早期的拉弦乐器）"}]}},"villages":{"lemma":"village"},"victimized":{"lemma":"victimize"},"visitors":{"lemma":"visitor"},"visited":{"lemma":"visit"},"viewers":{"lemma":"viewer"},"views":{"lemma":"view"},"vigor":{"lemma":"vigour","media":{"uk":"media/ldoce/hwd/bre/f/ld41vigor.mp3","us":"media/ldoce/hwd/ame/f/ld41vigor.mp3"}},"victims":{"lemma":"victim"},"viewed":{"lemma":"view"},"violinists":{"lemma":"violinist"},"visits":{"lemma":"visit"},"virtues":{"lemma":"virtue"},"viability":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if something is possible, it can be done or achieved","cn":""},{"en":"if an idea or plan is feasible, it is possible and you can find a practical way of doing it","cn":""},{"en":"possible and likely to be successful, and therefore worth doing","cn":""}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"The noun viability means the quality of being able to happen or having a reasonable chance of success. The viability of holding your party at a restaurant might depend on how many guests they can seat."}]},"collocations":{"phrases":["ADJ. continued, continuing, future, long-term She is very negative about the long-term viability of the project. | commercial, economic, fin","VERB + VIABILITY assess, explore, investigate, test | prove Once the railways had proved their viability expansion was rapid. | ensure | mai"]},"media":{"uk":"media/ldoce/hwd/bre/2/viable0205.mp3","us":"media/ldoce/hwd/ame/e/viable.mp3"},"examples":[{"en":"commercial viability","cn":"商业上的可行性"},{"en":"The committee came forward with one viable solution.","cn":""}],"oxford":{"phon":"ˌvaɪəˈbɪləti","pos":"noun","senses":[{"en":"the fact that something can be done and can be successful","cn":"某事可以做并且可以成功的事实","ex":{"en":"There are doubts about the commercial viability of the newspaper.","cn":"有人怀疑该报纸的商业可行性。"}},{"en":"the fact that something is capable of developing and surviving independently","cn":"某物能够独立发展和生存的事实","lab":"biology","ex":{"en":"the viability of the fetus","cn":"胎儿的生存能力"}}]}},"visualize":{"collins":{"senses":[{"pos":"VERB 动词","cn":"使形象化;想象;设想","en":"If you visualize something, you imagine what it is like by forming a mental picture of it.","ex":{"en":"Susan visualized her wedding day and saw herself walking down the aisle on her father's arm","cn":"苏珊想象着婚礼日当天的情景——自己挽着父亲的手臂走在教堂的过道上。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to form a picture or idea in your mind about what something might be like","cn":""},{"en":"to form a picture of someone or something in your mind, especially something that is definitely going to happen or exist in the future","cn":""},{"en":"to form a clear picture of something or someone in your mind","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To visualize something is to be able to see it in your mind. From the twitching in their feet, it seems that sleeping dogs often visualize a fenced-in area and about 30 squirrels."}]},"collocations":{"phrases":["ADV. easily","VERB + VISUALIZE be able/unable to, can/could I could visualize the scene in the office. | try to | be easy to | be difficult to, be hard to","PREP. as I visualized him as a typical businessman."]},"media":{"uk":"media/ldoce/hwd/bre/3/visualize0205.mp3","us":"media/ldoce/hwd/ame/a/laadvisualize.mp3"},"examples":[{"en":"It can help to visualize yourself making your speech clearly and confidently.","cn":"设想自己口齿清晰和充满信心地演讲是很有助益的。"},{"en":"I can't visualize what this room looked like before it was decorated.","cn":"我想像不出这个房间在装修之前是什么样子。"}],"oxford":{"phon":"ˈvɪʒuəlaɪz","pos":"verb","senses":[{"en":"to form a picture of somebody/something in your mind","cn":"使形象化；想象；构思；设想","ex":{"en":"Try to visualize him as an old man.","cn":"尽量设想他是一位老人。"}},{"en":"to make something able to be seen by the eye","cn":"使可视化；使看得见","lab":"specialist","ex":{"en":"Ultrasound is a technique that uses sound waves to visualize internal structures.","cn":"超声波扫描检查是利用声波透视人体内部结构的技术。"}}]}},"vibrate":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"（使）颤动;(使)振动;(使)抖动","en":"If something vibrates or if you vibrate it, it shakes with repeated small, quick movements.","ex":{"en":"The ground shook and the cliffs seemed to vibrate","cn":"大地在摇晃，悬崖好像在颤动。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to move suddenly from side to side or up and down, usually with a lot of force","cn":""},{"en":"to shake and make a noise","cn":""},{"en":"to shake continuously with small fast movements","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"When you feel something vibrate , it trembles and shakes. A mild earthquake, for example, might make your chandelier vibrate ."}]},"collocations":{"phrases":["ADV. gently","VERB + VIBRATE seem to","PREP. through The thuds vibrated through the car. | with The atmosphere seemed to vibrate with tension."]},"media":{"uk":"media/ldoce/hwd/bre/b/vibrate0205.mp3","us":"media/ldoce/hwd/ame/1/vibrate.mp3"},"examples":[{"en":"Every time a train went past the walls vibrated.","cn":"每当火车驶过，这些墙都会震动。"},{"en":"The atmosphere seemed to vibrate with tension.","cn":"气氛似乎紧张得发颤。"}],"oxford":{"phon":"vaɪˈbreɪt","pos":"verb","senses":[{"en":"to move or make something move from side to side very quickly and with small movements","cn":"（使）振动，颤动，摆动","ex":{"en":"Every time a train went past the walls vibrated.","cn":"每当火车驶过，这些墙都会震动。"}}]}},"viscount":{"collins":{"senses":[{"pos":"N-COUNT; N-TITLE 可数名词；头衔名词","cn":"（英国的）子爵","en":"A viscount is a British nobleman who is below an earl and above a baron in rank.","ex":{"en":"...a biography of Viscount Mourne.","cn":"一部关于莫恩子爵的传记"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a British nobleman with a rank between that of an earl and a baron 〔","cn":"英国的〕子爵"}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41viscount.mp3","us":"media/ldoce/hwd/ame/6/ld41viscount.mp3"},"oxford":{"phon":"ˈvaɪkaʊnt","pos":"noun","senses":[{"en":"(in the UK) a nobleman of a rank below an earl and above a baron","cn":"子爵（英国贵族，低于伯爵而高于男爵）"}]}},"victorious":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"获胜的;战胜的;胜利的","en":"You use victorious to describe someone who has won a victory in a struggle, war, or competition.","ex":{"en":"In 1978 he played for the victorious Argentinian side in the World Cup.","cn":"1978年，他效力于获得世界杯冠军的阿根廷队。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"achieving what you wanted, or having the effect or result you intended","cn":""},{"en":"having the effect or result that was wanted – used especially about treatments, drugs, or methods","cn":""},{"en":"successful as a result of winning in a game, election, war etc","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"When you're victorious , you've won something. A victorious team is triumphant."}]},"collocations":{"phrases":["VERBS be, emerge, prove Osborne emerged victorious after the second round of voting.","ADV. eventually, ultimately Against all the odds, Frederick II was ultimately victorious.","PREP. in victorious in the election | over The Reds were victorious over the Whites."]},"media":{"uk":"media/ldoce/hwd/bre/9/victorious0205.mp3","us":"media/ldoce/hwd/ame/9/victorious.mp3"},"examples":[{"en":"He emerged victorious in the elections.","cn":"他在竞选中脱颖而出获得胜利。"},{"en":"the victorious army/team","cn":"胜利之师；获胜的队"}],"oxford":{"phon":"vɪkˈtɔːriəs","pos":"adjective","senses":[{"en":"having won a victory; that ends in victory","cn":"胜利的；获胜的；战胜的","ex":{"en":"the victorious army/team","cn":"胜利之师；获胜的队"}}]}},"visceral":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"出自内心的;发自肺腑的","en":"Visceral feelings are feelings that you feel very deeply and find it difficult to control or ignore, and that are not the result of thought.","ex":{"en":"I never overcame a visceral antipathy for the monarchy.","cn":"我从未能够消除内心对君主政体的反感。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"visceral beliefs and attitudes are the result of strong feelings rather than careful thought 〔","cn":"信仰﹑态度〕出自内心的﹐发自肺腑的﹔(未经认真思考而)出于感情的"},{"en":"relating to the viscera","cn":"内脏的﹐脏腑的"}]},"vocab":{"pos":"1 adj 2 adj","senses":[{"en":"When something's visceral , you feel it in your guts. A visceral feeling is intuitive — there might not be a rational explanation, but you feel that you know what's best, like your visceral reaction against egg salad."}]},"media":{"uk":"media/ldoce/hwd/bre/2/visceral0205.mp3","us":"media/ldoce/hwd/ame/7/laadvisceral.mp3"},"examples":[{"en":"She had a visceral dislike of all things foreign.","cn":"凡是外国的东西，她都打心眼儿里讨厌。"},{"en":"his visceral hatred of the ruling class","cn":"他对统治阶级发自肺腑的仇恨"}],"oxford":{"phon":"ˈvɪsərəl","pos":"adjective","senses":[{"en":"resulting from strong feelings rather than careful thought","cn":"（未经过认真思考而）出自内心的，发自肺腑的","lab":"literary","ex":{"en":"visceral fear","cn":"发自内心的恐惧"}},{"en":"relating to the viscera","cn":"内脏的；脏器的","lab":"anatomy"}]}},"viewer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"电视（节目）观众","en":"Viewers are people who watch television, or who are watching a particular programme on television.","ex":{"en":"These programmes are each watched by around 19 million viewers every week.","cn":"这些电视节目的观众各自都在每周1,900万左右。"}},{"pos":"N-COUNT 可数名词","cn":"观看者;观察者","en":"A viewer is someone who is looking carefully at a picture or other interesting object.","ex":{"en":"... the relationship between the art object and the viewer.","cn":"艺术品与其观赏者之间的关系"}},{"pos":"N-COUNT 可数名词","cn":"（看幻灯片的）观片器，看片器","en":"A viewer is a device shaped like a box with a lens in one side. It is used for looking at transparent colour photographs.","ex":{"en":"This special viewer is simple to use and comes with 70 full-colour slides.","cn":"这个特别的观片器操作简单，配有70张全彩幻灯片。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who watches television - used especially by people in the television business","cn":""},{"en":"someone who listens to the radio - used especially by people in the radio business","cn":""},{"en":"all the people who watch or listen to a particular programme","cn":""}]},"collocations":{"phrases":["ADJ. television/TV | armchair While fewer people are attending football matches, armchair viewers are growing in number.","VERB + VIEWER attract, pull (in) The evening news is to change its serious image in a bid to attract more viewers. | be a hit with The new s","VIEWER + VERB see sth, watch sth BBC viewers saw the prim e minister lose his cool on las t night's &lsquo;Question Time&rsquo;. It i s esti"]},"media":{"uk":"media/ldoce/hwd/bre/d/viewer0205.mp3","us":"media/ldoce/hwd/ame/3/viewer.mp3"},"examples":[{"en":"Some of her art is intended to shock the viewer.","cn":"她的某些艺术作品旨在震撼观赏者。"},{"en":"The programme attracted millions of viewers.","cn":"这个节目吸引了数百万电视观众。"}],"oxford":{"phon":"ˈvjuːə(r)","pos":"noun","senses":[{"en":"a person watching television or a video on the internet","cn":"电视（或网络视频）观众","lab":"British English","ex":{"en":"The programme attracted millions of viewers.","cn":"这个节目吸引了数百万电视观众。"}},{"en":"a person who looks at or considers something","cn":"观看者；观察者","ex":{"en":"Some of her art is intended to shock the viewer.","cn":"她的某些艺术作品旨在震撼观赏者。"}},{"en":"a device for looking at slides (= photographs on special film), for example a small box with a light in it","cn":"（幻灯片）观看器；幻灯机"}]}},"viscous":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（液体）黏性的，黏稠的","en":"A viscous liquid is thick and sticky.","ex":{"en":"...dark, viscous blood.","cn":"黑色、黏稠的血液"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a viscous liquid is thick and sticky and does not flow easily 〔","cn":"液体〕黏滞的﹐黏稠的"}]},"vocab":{"pos":"adj","senses":[{"en":"Viscous means sticky, gluey and syrupy. So if something is viscous , you usually don't want to stick your fingers in it — that goes for boogers and maple syrup alike."}]},"media":{"uk":"media/ldoce/hwd/bre/8/viscous0205.mp3","us":"media/ldoce/hwd/ame/e/viscous.mp3"},"examples":[{"en":"As the liquid cools, it becomes viscous.","cn":"这液体冷却后会变黏稠。"}],"oxford":{"phon":"ˈvɪskəs","pos":"adjective","senses":[{"en":"thick and sticky; not flowing freely","cn":"黏稠的；黏滞的"}]}},"victor":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"胜利者;获胜者","en":"The victor in a battle or contest is the person who wins."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a person who has won a competition, especially in sport","cn":""},{"en":"the winner in a war, election, or important sporting event","cn":""},{"en":"having won an important fight, competition, election, etc","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"The victor is the winner of a contest, usually one that requires physical skills or strength, like in battle or sports. Calling someone the victor implies that he or she triumphed in a difficult competition."}]},"collocations":{"phrases":["ADJ. clear, runaway | worthy","VERB + VICTOR be, emerge (as) The team emerged as worthy victors.","PREP. ~ over The French pair fought back to finish two sets to one victors over the Williams sisters."]},"media":{"uk":"media/ldoce/hwd/bre/7/victor0205.mp3","us":"media/ldoce/hwd/ame/6/victor.mp3"},"examples":[{"en":"After the game the victors returned in triumph.","cn":"比赛结束后﹐得胜者凯旋。"}],"oxford":{"phon":"ˈvɪktə(r)","pos":"noun","senses":[{"en":"the winner of a battle, competition, game, etc.","cn":"胜利者；获胜者","ex":{"en":"The team emerged as clear victors in the competition.","cn":"该队脱颖而出成为比赛中显而易见的获胜者。"}},{"en":"a first name for boys","cn":"维克托（男子名）","pos":""}]}},"virtuosity":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（艺术家、运动员等的）精湛技艺，高超技巧","en":"The virtuosity of someone such as an artist or sports player is their great skill.","ex":{"en":"At that time, his virtuosity on the trumpet had no parallel in jazz.","cn":"那时，他高超的小号吹奏技巧在爵士乐界无人能比。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a very high degree of skill in performing 〔","cn":"表演方面的〕精湛技巧﹐高超技艺"}]},"vocab":{"pos":"n","senses":[{"en":"Use the noun virtuosity to describe an impressive skill, such as a classical musician's virtuosity at playing the cello."}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41virtuosity.mp3","us":"media/ldoce/hwd/ame/c/virtuosity.mp3"},"examples":[{"en":"a performance of breathtaking virtuosity","cn":"技艺令人叫绝的演出"},{"en":"technical virtuosity","cn":"技术的娴熟"}],"oxford":{"phon":"ˌvɜːtʃuˈɒsəti","pos":"noun","senses":[{"en":"a very high degree of skill in performing or playing","cn":"（表演或演奏方面的）高超技艺，精湛演技","ex":{"en":"technical virtuosity","cn":"技术的娴熟"}}]}},"viper":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"蝰蛇","en":"A viper is a small poisonous snake found mainly in Europe."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small poisonous snake","cn":"蝰蛇"},{"en":"someone who behaves in an unpleasant way and harms other people","cn":"阴险恶毒的人"}]},"vocab":{"pos":"n","senses":[{"en":"A viper is a certain type of poisonous snake. The most common vipers in the United States are rattlesnakes and water moccasins."}]},"media":{"uk":"media/ldoce/hwd/bre/1/viper0205.mp3","us":"media/ldoce/hwd/ame/9/viper.mp3"},"oxford":{"phon":"ˈvaɪpə(r)","pos":"noun","senses":[{"en":"a small poisonous snake","cn":"蝰蛇（一种小毒蛇）"},{"en":"a person who harms other people","cn":"毒如蛇蝎的人；险恶的人","lab":"formal"}]}},"vindicate":{"collins":{"senses":[{"pos":"VERB 动词","cn":"证实;证明…正确;证明…无辜","en":"If a person or their decisions, actions, or ideas are vindicated, they are proved to be correct, after people have said that they were wrong.","ex":{"en":"The director said he had been vindicated by the experts' report","cn":"主任说专家们的报告证明了他是正确的。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to prove that someone who was blamed for something is in fact not guilty","cn":"证明…无辜[无罪]"},{"en":"to prove that someone or something is right or true","cn":"证实﹐证明"}]},"vocab":{"pos":"v","senses":[{"en":"Vindicate means to justify, prove, or reinforce an idea — or to absolve from guilt. If your family thinks you hogged the last piece of pie on Thanksgiving, you'll be vindicated when your younger brother fesses up."}]},"media":{"uk":"media/ldoce/hwd/bre/d/vindicate0205.mp3","us":"media/ldoce/hwd/ame/4/vindicate.mp3"},"examples":[{"en":"Anti-nuclear protesters regarded the Chernobyl accident as a clear vindication of their campaign.","cn":"反核示威者认为，切尔诺贝利核电站核泄漏事故清楚地表明他们的反核运动是正确的。"},{"en":"I have every confidence that this decision will be fully vindicated.","cn":"我完全相信这一决定的正确性将得到充分证明。"}],"oxford":{"phon":"ˈvɪndɪkeɪt","pos":"verb","senses":[{"en":"to prove that something is true or that you were right to do something, especially when other people had a different opinion","cn":"证实；证明有理","ex":{"en":"I have every confidence that this decision will be fully vindicated.","cn":"我完全相信这一决定的正确性将得到充分证明。"}},{"en":"to prove that somebody is not guilty when they have been accused of doing something wrong or illegal; to prove that somebody is right about something","cn":"澄清（责难或嫌疑）；证明（某人）无罪（责）；证明（某人）是对的","ex":{"en":"New evidence emerged, vindicating him completely.","cn":"新证据出现了，证明他完全是无辜的。"}}]}},"vie":{"collins":{"senses":[{"pos":"V-RECIP 相互动词","cn":"竞争;争夺","en":"If one person or thing is vying with another for something, the people or things are competing for it.","ex":{"en":"California is vying with other states to capture a piece of the growing communications market","cn":"为了在日渐扩大的通讯市场分得一杯羹，加利福尼亚正在和其他州展开竞争。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to try to do better than another person or organization, for example in business or politics","cn":""},{"en":"to try extremely hard to get an important job or political position that other people are also trying to get","cn":""},{"en":"if two people, organizations etc vie with each other in order to do something, they compete in order to try to do it","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To vie for something means to compete for it. Two teams may vie for the gold medal, but one will have to go home with silver."}]},"media":{"uk":"media/ldoce/hwd/bre/7/vie0205.mp3","us":"media/ldoce/hwd/ame/9/vie.mp3"},"examples":[{"en":"Screaming fans vied to get closer to their idol.","cn":"尖声喊叫的崇拜者争先恐后地涌向他们的偶像。"},{"en":"She was surrounded by men all vying for her attention.","cn":"她周围尽是争相博得她青睐的男子。"}],"oxford":{"phon":"vaɪ","pos":"verb","senses":[{"en":"to compete strongly with somebody in order to obtain or achieve something","cn":"激烈竞争；争夺","ex":{"en":"She was surrounded by men all vying for her attention.","cn":"她周围尽是争相博取她青睐的男子。"}}]}},"visage":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"脸;面容","en":"Someone's visage is their face.","ex":{"en":"...his milky-white innocent visage.","cn":"他白嫩无邪的面孔"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a face 〔","cn":"人的〕脸"}]},"vocab":{"pos":"n","senses":[{"en":"Visage is a literary term for referring to someone's face or facial features. You may notice that some face creams use the word visage to try to sound fancier than they are."}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41visage.mp3","us":"media/ldoce/hwd/ame/0/visage.mp3"},"oxford":{"phon":"ˈvɪzɪdʒ","pos":"noun","senses":[{"en":"a person’s face","cn":"（人的）脸，面容"}]}},"villainous":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"恶棍似的;流氓般的;邪恶的;可憎的","en":"A villainous person is very bad and willing to harm other people or break the law in order to get what he or she wants.","ex":{"en":"...her villainous father.","cn":"她那个恶棍父亲"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"evil or criminal","cn":"恶毒的﹐邪恶的﹔罪恶的"}]},"vocab":{"pos":"adj","senses":[{"en":"To be villainous is to be evil, wicked, and despicable, like a bad guy in a movie or a villainous bus driver who sees you but doesn’t stop."}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41villainous.mp3","us":"media/ldoce/hwd/ame/c/villainous.mp3"},"oxford":{"phon":"ˈvɪlənəs","pos":"adjective","senses":[{"en":"very evil; very unpleasant","cn":"邪恶的；可憎的"}]}},"vicar":{"collins":{"senses":[{"pos":"N-COUNT; N-VOC 可数名词；称呼名词","cn":"（英国国教的）教区牧师，教区教堂主持","en":"A vicar is an Anglican priest who is in charge of a church and the area it is in, which is called a parish."},{"pos":"N-COUNT; N-VOC 可数名词；称呼名词","cn":"（美国新教圣公会的）教堂主持,教区牧师","en":"A vicar is a priest who is in charge of a chapel that is associated with a parish church in the Episcopal Church in the United States."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who is specially trained to perform religious duties and ceremonies in the Christian church","cn":""},{"en":"a priest of high rank in some branches of the Christian church, who is the head of all the churches and priests in a large area","cn":""},{"en":"a priest in the Church of England who is in charge of a church in a particular area 〔","cn":"英国国教的〕代牧，教区牧师"}]},"vocab":{"pos":"n","senses":[{"en":"A vicar is a member of the clergy who is not high-ranking but is still considered a holy representative of the church."}]},"media":{"uk":"media/ldoce/hwd/bre/c/vicar0205.mp3","us":"media/ldoce/hwd/ame/c/vicar.mp3"},"oxford":{"phon":"ˈvɪkə(r)","pos":"noun","senses":[{"en":"an Anglican priest who is in charge of a church and the district around it (called a parish)","cn":"（圣公会的）代牧，教区牧师","lab":"especially British English"},{"en":"a priest in the US Episcopal Church","cn":"（美国圣公会的）牧师","lab":"North American English"}]}},"vineyard":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（种植酿酒葡萄的）葡萄园;葡萄酒厂","en":"A vineyard is an area of land where grape vines are grown in order to produce wine. You can also use vineyard to refer to the set of buildings in which the wine is produced."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"one of a number of small round green or purple fruits that grow together on a vine . Grapes are often used for making wine","cn":""},{"en":"a plant that produces grapes","cn":""},{"en":"a piece of land where grapevines are grown in order to produce wine 〔","cn":"为酿酒而建的〕葡萄园"}]},"vocab":{"pos":"n","senses":[{"en":"If you dream of one day growing grapes and making wine in the South of France, you hope to work at a vineyard , another name for a farm where wine grapes are grown."}]},"media":{"img":["media/ldoce/img/vineyard.jpg"],"uk":"media/ldoce/hwd/bre/3/vineyard0205.mp3","us":"media/ldoce/hwd/ame/1/vineyard.mp3"},"oxford":{"phon":"ˈvɪnjəd","pos":"noun","senses":[{"en":"a piece of land where grapes are grown in order to produce wine; a business that produces wine from the grapes it grows in a vineyard","cn":"（为酿酒而种植的）葡萄园；（以自产葡萄进行生产的）葡萄酒厂","ex":{"en":"Dutch settlers planted the first vineyard when they arrived in 1652.","cn":"荷兰移民1652年抵达后种植了第一个葡萄园。"}}]}},"viscountess":{"collins":{"senses":[{"pos":"N-COUNT; N-TITLE 可数名词；头衔名词","cn":"子爵夫人;女子爵","en":"A viscountess is the wife of a viscount or a woman who holds the same position as a viscount.","ex":{"en":"...Viscount and Viscountess Osborne.","cn":"奥斯本子爵和子爵夫人"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the wife of a viscount, or a woman who has the rank of a viscount","cn":"子爵夫人﹔女子爵"}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41viscountess.mp3","us":"media/ldoce/hwd/ame/9/ld41viscountess.mp3"},"oxford":{"phon":"ˈvaɪkaʊntəs","pos":"noun","senses":[{"en":"a woman who has the rank of a viscount","cn":"女子爵"},{"en":"the wife of a viscount","cn":"子爵夫人"}]}},"visionary":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"有远见的人;愿景家","en":"If you refer to someone as a visionary, you mean that they have strong, original ideas about how things might be different in the future, especially about how things might be improved.","ex":{"en":"Visionaries are constantly fighting conventional wisdom because they see the world ahead in terms of what it can be","cn":"愿景家总在不断挑战传统思维，因为他们是用超前的眼光看待这个世界的。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有远见的;愿景的","en":"You use visionary to describe the strong, original ideas of a visionary.","ex":{"en":"Many are hailing Rendell's ideas as visionary.","cn":"许多人都称赞伦德尔的想法很有远见。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having clear ideas of what the world should be like in the future","cn":"有远见的﹐有眼光的"},{"en":"existing only in someone’s mind and unlikely to ever exist in the real world","cn":"梦幻中的﹔空想的"},{"en":"someone who has clear ideas and strong feelings about the way something should be in the future","cn":"有远见的人"}]},"vocab":{"pos":"n adj","senses":[{"en":"You've got big ideas. Crazy ideas. But forward thinking ideas — ideas that just might change the way the world works. You're considered a visionary ."}]},"media":{"uk":"media/ldoce/hwd/bre/f/visionary_adj0205.mp3","us":"media/ldoce/hwd/ame/2/visionary1.mp3"},"examples":[{"en":"a visionary leader","cn":"有远见卓识的领袖"},{"en":"visionary experiences","cn":"异象体验"}],"oxford":{"phon":"ˈvɪʒənri","pos":"adjective","senses":[{"en":"original and showing the ability to think about or plan the future with great imagination and intelligence","cn":"有眼力的；有创见的；有远见卓识的","lab":"approving","ex":{"en":"a visionary leader","cn":"有远见卓识的领袖"}},{"en":"relating to dreams or strange experiences, especially of a religious kind","cn":"梦幻的；（尤指）宗教异象的；神示的","ex":{"en":"visionary experiences","cn":"异象体验"}},{"en":"a person who has the ability to think about or plan the future in a way that is intelligent and shows imagination","cn":"有眼力的人；有远见卓识的人","ex":{"en":"She was a true visionary.","cn":"她是一位真正的有远见的人。"},"pos":"noun"}]}},"vibrato":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"（乐曲中的）颤音,颤动效果","en":"Vibrato is a rapidly repeated slight change in the pitch of a musical note. Singers and musicians use vibrato to make the music sound more emotional.","ex":{"en":"I encourage oboe and clarinet players to use plenty of vibrato.","cn":"我鼓励演奏双簧管和单簧管的乐手们多使用颤音。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a way of singing or playing a musical note so that it goes up and down very slightly in pitch 〔","cn":"演唱或演奏的〕颤动效果﹐颤音﹔颤吟﹔揉弦"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41vibrato.mp3","us":"media/ldoce/hwd/ame/7/vibrato.mp3"},"oxford":{"phon":"vɪˈbrɑːtəʊ","pos":"noun","senses":[{"en":"a shaking effect in singing or playing a musical instrument, made by rapid, slight changes in pitch (= how high or low a sound is)","cn":"（演唱或演奏的）颤音效果，颤音"}]}},"viable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"切实可行的;能办到的","en":"Something that is viable is capable of doing what it is intended to do.","ex":{"en":"Cash alone will not make Eastern Europe's banks viable","cn":"仅靠现金不能使东欧的银行维持下去。"}},{"pos":"ADJ 形容词","cn":"能存活的;能生长发育的","en":"Foetuses, seeds, or eggs are described as viable if they are capable of developing into living beings without outside help.","ex":{"en":"Five viable pregnancies were established.","cn":"已确定5个胎儿能够成活。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if something is possible, it can be done or achieved","cn":""},{"en":"if an idea or plan is feasible, it is possible and you can find a practical way of doing it","cn":""},{"en":"possible and likely to be successful, and therefore worth doing","cn":""}]},"vocab":{"pos":"1 adj 2 adj","senses":[{"en":"When something is viable , the adjective refers to something workable with the ability to grow and function properly."}]},"collocations":{"phrases":["VERBS be, prove, seem, sound None of the projects proved financially viable. | become | remain | make sth It is only their investment that m","ADV. extremely, truly | perfectly a perfectly viable form of political organization | potentially | still | no longer | commercially, econom"]},"media":{"uk":"media/ldoce/hwd/bre/2/viable0205.mp3","us":"media/ldoce/hwd/ame/e/viable.mp3"},"examples":[{"en":"There is no viable alternative.","cn":"没有其他可行的措施。"},{"en":"to be commercially/politically/financially/economically viable","cn":"在商业上/政治上/财政上/经济上可行"}],"oxford":{"phon":"ˈvaɪəbl","pos":"adjective","senses":[{"en":"that can be done; that will be successful","cn":"可实施的；切实可行的","ex":{"en":"a viable option/proposition","cn":"切实可行的选择／提议"}},{"en":"capable of developing and surviving independently","cn":"可生存的；能独立发展的；能独立生存的；可生长发育的","lab":"biology","ex":{"en":"viable organisms","cn":"可存活的生物"}}]}},"virgin":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"处女;童男","en":"A virgin is someone who has never had sex.","ex":{"en":"I was a virgin until I was thirty years old","cn":"我30岁前一直是个处女。"}},{"pos":"ADJ 形容词","cn":"（土地等）未使用的，未开发的","en":"You use virgin to describe something such as land that has never been used or spoiled.","ex":{"en":"Within 40 years there will be no virgin forest left.","cn":"过不了40年，就将不会再有未开发的森林了。"}},{"pos":"PHRASE 短语","cn":"陌生的情形;全新的领域","en":"If you say that a situation is virgin territory, you mean that you have no experience of it and it is completely new for you."},{"pos":"N-COUNT 可数名词","cn":"新手;雏儿；完全无经验的人","en":"You can use virgin to describe someone who has never done or used a particular thing before.","ex":{"en":"Until he appeared in 'In the Line of Fire' Malkovich had been an action-movie virgin","cn":"出演《火线狙击》以前，马尔科维奇从未演过动作片。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who has never had sex","cn":"处女﹔童男"},{"en":"someone who is celibate has chosen not to have sex at all, especially for religious reasons","cn":""},{"en":"a platonic relationship is one between people who do not have sex with each other, but are just friends - use this especially when other people think they are having a sexual relationship","cn":""}]},"vocab":{"pos":"n adj","senses":[{"en":"A virgin is someone who has never had sex. After you have sex, you've lost your virginity . We can also say an unharvested forest is a virgin forest."}]},"media":{"uk":"media/ldoce/hwd/bre/c/brelasdevirgin.mp3","us":"media/ldoce/hwd/ame/4/virgin1.mp3"},"examples":[{"en":"the virgin birth (= the belief that Mary was a virgin before and after giving birth to Jesus)","cn":"圣母玛利亚童贞生子"},{"en":"virgin snow (= fresh and not marked)","cn":"新雪"}],"oxford":{"phon":"ˈvɜːdʒɪn","pos":"noun","senses":[{"en":"a person who has never had sex","cn":"处女；童男","g":"[countable]","ex":{"en":"She was a virgin when she got married.","cn":"她结婚时还是处女。"}},{"en":"the Virgin Mary, mother of Jesus Christ","cn":"童贞马利亚（耶稣之母）","g":"[singular]"},{"en":"a person who has no experience of a particular activity","cn":"无…经验的人；新手","g":"[countable]","ex":{"en":"a political virgin","cn":"无政治经验的人"}},{"en":"in its original pure or natural condition and not changed, touched or made less good","cn":"未开发的；原始状态的；天然的；未遭破坏的","g":"[usually before noun]","ex":{"en":"virgin forest/land/territory","cn":"原始森林；处女地；未开发地区"},"pos":"adjective"},{"en":"with no sexual experience","cn":"处女的；贞洁的；童贞的","g":"[only before noun]","ex":{"en":"a virgin bride","cn":"贞洁的新娘"},"pos":"adjective"},{"en":"a British company formed in 1970 by Richard Branson. It began as a record company, producing and selling records through its own shops. In 1984 it introduced an airline service, Virgin Atlantic. The Virgin Group now offers many other products and services, including financial and travel services and healthcare. It also has a radio station, Virgin Radio. It also operates some train services in Britain.","cn":"处女：由Richard Branson于1970年成立的英国公司。它最初是一家唱片公司，通过自己的商店生产和销售唱片。1984年，它引入了维珍航空的航空服务。维珍集团现在提供许多其他产品和服务，包括金融和旅游服务以及医疗保健。它还有一个广播电台，维珍广播电台。它还在英国经营一些火车服务。","pos":""}]}},"visor":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（头盔上的）面罩，面甲，护面","en":"A visor is a movable part of a helmet which can be pulled down to protect a person's eyes or face.","ex":{"en":"He pulled on a battered old crash helmet with a scratched visor.","cn":"他戴上了一顶破旧的防护头盔，上面的面罩已有划痕。"}},{"pos":"N-COUNT 可数名词","cn":"（汽车内挡风玻璃上方的）遮阳板","en":"A visor is a piece of plastic or other material fixed above the windscreen inside a car, which can be turned down to protect the driver's eyes from bright sunshine.","ex":{"en":"I put down the sun visor to shade my eyes from the light.","cn":"我拉下遮阳板来遮挡耀眼的阳光。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the part of a helmet (= protective hard hat ) that can be lowered to protect your face 〔","cn":"头盔上可放下来保护脸部的〕面甲﹐脸盔﹐护面"},{"en":"the curved part of a cap that sticks out in front above your eyes","cn":"帽舌"},{"en":"a flat object fixed above the front window inside a car that can be moved down to keep the sun out of your eyes 〔","cn":"汽车内挡风玻璃上方的〕遮阳板"}]},"vocab":{"pos":"n","senses":[{"en":"A visor is part of the front of a helmet that can usually be raised or lowered. Visors shade your eyes from the sun."}]},"media":{"img":["media/ldoce/img/visor.jpg"],"uk":"media/ldoce/hwd/bre/8/visor0205.mp3","us":"media/ldoce/hwd/ame/a/visor.mp3"},"oxford":{"phon":"ˈvaɪzə(r)","pos":"noun","senses":[{"en":"a part of a helmet that can be pulled down to protect the eyes and face","cn":"（头盔上的）面甲，面罩，护面"},{"en":"a curved piece of plastic, etc. worn on the head above the eyes to protect them from the sun","cn":"遮阳帽舌"},{"en":"a small piece of plastic, etc. inside the front window of a car that can be pulled down to protect the driver’s eyes from the sun","cn":"（汽车内挡风玻璃上方的）遮阳板"},{"en":"the stiff front part of a cap that sticks out above your eyes","cn":"帽舌；帽檐","lab":"both North American English"}]}},"victoriana":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"维多利亚（女王)时代的物品","en":"Interesting or valuable objects made in the time of Queen Victoria are sometimes referred to as Victoriana ."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"objects made during the Victorian period","cn":"维多利亚时代的物品"}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41victoriana.mp3","us":"media/ldoce/hwd/ame/1/ld41victoriana.mp3"},"oxford":{"phon":"ˌvɪktɔːriˈɑːnə","pos":"noun","senses":[{"en":"objects made during the rule of Queen Victoria (1837-1901), especially when they are for sale or as part of a collection","cn":"维多利亚娜：维多利亚女王（1837-1901）统治时期制造的物品，尤其是在出售或收藏时","ex":{"en":"She runs a stall selling old dolls, china plates and other Victoriana.","cn":"她经营着一个摊位，出售旧娃娃、瓷盘和其他维多利亚时期的物品。"}}]}},"vicious":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"残暴的;凶残的;凶恶的","en":"A vicious person or a vicious blow is violent and cruel.","ex":{"en":"He was a cruel and vicious man","cn":"他是一个残忍凶狠的男人。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"恶毒的;恶意的;不怀好意的","en":"A vicious remark is cruel and intended to upset someone.","ex":{"en":"It is a deliberate, nasty and vicious attack on a young man's character.","cn":"这是对一个年轻人品格蓄意的、卑鄙的、恶毒的攻击。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"deliberately hurting people or making them suffer","cn":""},{"en":"not feeling any pity and not caring about other people or their problems","cn":""},{"en":"getting pleasure from making other people suffer","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Vicious is an adjective that means intentionally harmful or nasty. If you spread vicious rumors about a person, you're telling people things that will hurt her feelings or ruin her reputation. Cut it out!"}]},"collocations":{"phrases":["VERBS be, look, sound | become, get, turn The computer wars are going to get vicious over the next few years.","ADV. particularly, truly, very a particularly vicious and brutal crime | increasingly | rather"]},"media":{"uk":"media/ldoce/hwd/bre/5/vicious0205.mp3","us":"media/ldoce/hwd/ame/c/vicious.mp3"},"examples":[{"en":"Police were shocked by the viciousness of the assault.","cn":"警方对这一攻击的残忍感到震惊。"},{"en":"She wrote me a vicious letter.","cn":"她给我写了一封严厉的信。"}],"oxford":{"phon":"ˈvɪʃəs","pos":"adjective","senses":[{"en":"violent and cruel","cn":"狂暴的；残酷的","ex":{"en":"a vicious attack","cn":"猛烈的攻击"}},{"en":"aggressive and dangerous","cn":"凶猛危险的","ex":{"en":"a vicious dog","cn":"恶犬"}},{"en":"full of hate and anger","cn":"充满仇恨的；严厉的","ex":{"en":"She wrote me a vicious letter.","cn":"她给我写了一封严厉的信。"}},{"en":"very bad or severe","cn":"恶劣的；严重的","lab":"informal","ex":{"en":"a vicious headache","cn":"剧烈的头痛"}}]}},"vibrator":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"振动按摩器;颤震器","en":"A vibrator is an electric device which vibrates. It is used in massage to reduce pain, or to give sexual pleasure."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a piece of electrical equipment that produces a small shaking movement, used especially in massage or to get sexual pleasure 〔","cn":"尤指按摩或获取性快感时用的〕振动器﹐振动按摩器"}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41vibrator.mp3","us":"media/ldoce/hwd/ame/6/vibrator.mp3"},"oxford":{"phon":"vaɪˈbreɪtə(r)","pos":"noun","senses":[{"en":"an electrical device that produces a continuous shaking movement, used in massage or for sexual pleasure","cn":"（用于按摩或产生性快感的）颤动按摩器，震动器"}]}},"vitreous":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"玻璃做的;玻璃般的","en":"Vitreous means made of glass or resembling glass."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"made of or looking like glass","cn":"玻璃造的﹔玻璃(状)的"}]},"vocab":{"pos":"adj","senses":[{"en":"Something that has the characteristics of glass — hard, brittle, glossy, possibly transparent — can be said to be vitreous , or glasslike. A vitreous surface works well for a kitchen counter."}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41vitreous.mp3","us":"media/ldoce/hwd/ame/8/vitreous.mp3"},"examples":[{"en":"vitreous enamel","cn":"玻璃釉"}],"oxford":{"phon":"ˈvɪtriəs","pos":"adjective","senses":[{"en":"hard, shiny and clear like glass","cn":"玻璃质的；玻璃状的；透明的","ex":{"en":"vitreous enamel","cn":"玻璃釉"}}]}},"violet":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"紫罗兰","en":"A violet is a small plant that has purple or white flowers in the spring."},{"pos":"COLOUR 颜色词","cn":"紫罗兰色;紫色","en":"Something that is violet is a bluish-purple colour.","ex":{"en":"The light was beginning to drain from a violet sky.","cn":"光线开始从紫罗兰色的天空渐渐消退。"}},{"pos":"PHRASE 短语","cn":"羞怯的人;腼腆的人","en":"If you say that someone is no shrinking violet, you mean that they are not at all shy.","ex":{"en":"When it comes to expressing himself he is no shrinking violet","cn":"他在表达自己的想法时毫不羞怯。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a plant with small dark purple flowers, or sometimes white or yellow ones","cn":"紫罗兰"},{"en":"a bluish-purple colour","cn":"蓝紫色﹐紫罗兰色"}]},"media":{"uk":"media/ldoce/hwd/bre/6/violet0205.mp3","us":"media/ldoce/hwd/ame/b/violet1.mp3"},"examples":[{"en":"dressed in violet","cn":"身着蓝紫色衣服的"},{"en":"violet eyes","cn":"蓝紫色的眼睛"}],"oxford":{"phon":"ˈvaɪələt","pos":"adjective","senses":[{"en":"between blue and purple in colour","cn":"蓝紫色；紫罗兰色","ex":{"en":"violet eyes","cn":"蓝紫色的眼睛"}},{"en":"a small wild or garden plant with purple or white flowers with a sweet smell that appear in spring","cn":"紫罗兰","g":"[countable]","pos":"noun"},{"en":"a colour between blue and purple","cn":"蓝紫色；紫罗兰色","g":"[uncountable]","ex":{"en":"dressed in violet","cn":"身着蓝紫色衣服的"},"pos":"noun"},{"en":"a first name for girls","cn":"维奥莉特（女子名）","pos":""}]}},"viaduct":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（架于山谷上的）高架桥，高架公路，高架铁路","en":"A viaduct is a long, high bridge that carries a road or a railway across a valley."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a long high bridge, especially one with arch es , that crosses a valley and has a road or railway on it 〔","cn":"架于山谷上的公路或铁路〕高架桥"}]},"vocab":{"pos":"n","senses":[{"en":"A viaduct is a bridge made of connected sections. Most viaducts are a series of arches that span a road."}]},"media":{"uk":"media/ldoce/hwd/bre/4/viaduct0205.mp3","us":"media/ldoce/hwd/ame/d/viaduct.mp3","img":["media/thumb/viaduct.jpg"]},"oxford":{"phon":"ˈvaɪədʌkt","pos":"noun","senses":[{"en":"a long, high bridge, usually with arches, that carries a road or railway across a river or valley","cn":"高架桥（通常有拱，横跨河道或山谷连通公路或铁路）","ex":{"en":"A train was crossing the viaduct.","cn":"一列火车正在穿过高架桥。"}}]}},"vignette":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（清晰介绍事物特征的）短文，简介，花絮","en":"A vignette is a short description, picture, or piece of acting which expresses very clearly and neatly the typical characteristics of the thing that it represents.","ex":{"en":"The book is an excellent vignette of some of the major debates in science.","cn":"这本书清晰而扼要地介绍了科学界的一些主要争议。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a short description in a book or play showing the typical features of a person or situation 〔","cn":"书或剧本中对人物或场景的〕简介"},{"en":"a small picture or design at the beginning or end of a book or chapter 〔","cn":"书或章节开篇或结尾处的〕小装饰图案﹐花饰"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"A vignette is a brief but powerful scene. A good vignette leaves you wanting more."}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41vignette.mp3","us":"media/ldoce/hwd/ame/4/vignette.mp3"},"oxford":{"phon":"vɪnˈjet","pos":"noun","senses":[{"en":"a short piece of writing or acting that clearly shows what a particular person, situation, etc. is like","cn":"（清晰展示人物特征、局势等的）短文，简介，花絮；（表演）片段，小品","ex":{"en":"a charming vignette of Edwardian life","cn":"爱德华时代生活的迷人小插曲"}},{"en":"a small picture or drawing, especially on the first page of a book","cn":"（尤指书名页上的）小花饰，小插图","ex":{"en":"Each vignette represents one of the four seasons.","cn":"每个小插图代表四个季节之一。"}}]}},"vitriol":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"尖刻的文字;刻薄的话;讽刺","en":"If you refer to what someone says or writes as vitriol, you disapprove of it because it is full of bitterness and hate, and so causes a lot of distress and pain.","ex":{"en":"The vitriol he hurled at members of the press knew no bounds","cn":"他对媒体的尖刻抨击没完没了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"very cruel and angry remarks that are intended to hurt someone’s feelings","cn":"尖刻[刻薄]的话﹔讽刺"},{"en":"sulphuric acid","cn":"硫酸"}]},"vocab":{"pos":"n v","senses":[{"en":"Vitriol is harsh, nasty criticism. You may have deserved some blame when the cake didn't rise, but the head chef's stream of vitriol was unnecessary."}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41vitriol.mp3","us":"media/ldoce/hwd/ame/3/vitriol.mp3"},"oxford":{"phon":"ˈvɪtriəl","pos":"noun","senses":[{"en":"very cruel and bitter comments or criticism","cn":"尖刻无情的话（或批评）"}]}},"vitamin":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"维生素;维他命","en":"Vitamins are substances that you need in order to remain healthy, which are found in food or can be eaten in the form of pills.","ex":{"en":"Butter, margarine, and oily fish are all good sources of vitamin D.","cn":"黄油、人造黄油和多脂鱼都含有丰富的维生素D。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a chemical substance in food that is necessary for good health","cn":"维生素"},{"en":"a pill containing vitamins","cn":"维生素(丸)"}]},"vocab":{"pos":"n","senses":[{"en":"A vitamin is an organic substance your body needs to keep working properly. Vitamins are important to health."}]},"collocations":{"phrases":["ADJ. take The doctor told me to take vitamins regularly.","VERB + VITAMIN contain Most foods contain vitamin E. | be rich in Fish is rich in vitamins and minerals. | enrich sth with, fortify sth with","VITAMIN + NOUN drops, injections, pills, supplements, tablets | requirements | deficiency Vitamin C deficiency can ultimately lead to scurvy"]},"media":{"uk":"media/ldoce/hwd/bre/4/brelasdevitamin.mp3","us":"media/ldoce/hwd/ame/4/vitamin.mp3"},"examples":[{"en":"breakfast cereals enriched with vitamins","cn":"增加了维生素的谷物早餐食品"},{"en":"vitamin deficiency","cn":"维生素缺乏"}],"oxford":{"phon":"ˈvɪtəmɪn","pos":"noun","senses":[{"en":"a natural substance found in food that is an essential part of what humans and animals need to help them grow and stay healthy. There are many different vitamins.","cn":"维生素；维他命","lab":"British English","ex":{"en":"vitamin A/B/D/E","cn":"维生素 A／B／D／E"}}]}},"villager":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"村民","en":"You refer to the people who live in a village, especially the people who have lived there for most or all of their lives, as the villagers .","ex":{"en":"Soon the villagers couldn't afford to buy food for themselves.","cn":"很快村民们就买不起口粮了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who lives in a village","cn":"村民"}]},"media":{"uk":"media/ldoce/hwd/bre/a/villager0205.mp3","us":"media/ldoce/hwd/ame/2/amelasdevillager.mp3"},"oxford":{"phon":"ˈvɪlɪdʒə(r)","pos":"noun","senses":[{"en":"a person who lives in a village","cn":"村民；乡村居民；乡下人","ex":{"en":"Some of the villagers have lived here all their lives.","cn":"一些村民在这里生活了一辈子。"}}]}},"viewfinder":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（照相机的）取景器","en":"A viewfinder is a small square of glass in a camera that you look through in order to see what you are going to photograph."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the small square of glass on a camera that you look through to see exactly what you are photographing 〔","cn":"照相机的〕取景器"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41viewfinder.mp3","us":"media/ldoce/hwd/ame/9/viewfinder.mp3"},"oxford":{"phon":"ˈvjuːfaɪndə(r)","pos":"noun","senses":[{"en":"the part of a camera that you look through to see the area that you are photographing","cn":"（照相机的）取景器"}]}},"virtuous":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有德行的;道德高尚的;正直的","en":"A virtuous person behaves in a moral and correct way.","ex":{"en":"Louis was shown as an intelligent, courageous and virtuous family man.","cn":"路易斯在人们眼里是一个智慧、勇敢、品德高尚的顾家男人。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"自命不凡的;自鸣得意的","en":"If you describe someone as virtuous, you mean that they have done what they ought to do and feel very pleased with themselves, perhaps too pleased.","ex":{"en":"I cleaned the flat, which left me feeling virtuous.","cn":"我打扫了整个公寓，这让我觉得自己很了不起。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"kind, honest, and helpful","cn":""},{"en":"someone who is decent is good and honest according to the normal standards of society","cn":""},{"en":"behaving and living your life in a way that is considered morally correct by society, especially because of the family you come from","cn":""}]},"vocab":{"pos":"1 adj 2 adj","senses":[{"en":"Virtuous is “good” with a halo. If you call someone virtuous , you are saying that person is living according to high moral standards. Someone virtuous is who you want leading your Girl Scout troop."}]},"media":{"uk":"media/ldoce/hwd/bre/c/virtuous0205.mp3","us":"media/ldoce/hwd/ame/f/virtuous.mp3"},"examples":[{"en":"He was feeling virtuous because he had finished and they hadn't.","cn":"因为他完成了而他们没有，他自以为了不起。"},{"en":"She lived an entirely virtuous life.","cn":"她一生品行端正。"}],"oxford":{"phon":"ˈvɜːtʃuəs","pos":"adjective","senses":[{"en":"behaving in a very good and moral way; showing high moral standards","cn":"品行端正的；道德高尚的","lab":"formal","ex":{"en":"a wise and virtuous man","cn":"博学多识的君子"}},{"en":"claiming to behave better or have higher moral standards than other people","cn":"自命不凡的；自命清高的","lab":"disapproving or humorous","ex":{"en":"He was feeling virtuous because he had finished and they hadn't.","cn":"因为他完成了而他们没有，他自以为了不起。"}}]}},"vicarage":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"教区牧师住所","en":"A vicarage is a house in which a vicar lives."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a house where a vicar lives","cn":"教区牧师的住宅"}]},"media":{"uk":"media/ldoce/hwd/bre/b/vicarage0205.mp3","us":"media/ldoce/hwd/ame/8/vicarage.mp3"},"oxford":{"phon":"ˈvɪkərɪdʒ","pos":"noun","senses":[{"en":"a vicar’s house","cn":"代牧住宅"}]}},"vile":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"糟糕透顶的;讨厌的;恶劣的","en":"If you say that someone or something is vile, you mean that they are very unpleasant.","ex":{"en":"The weather was consistently vile","cn":"天气一直很糟糕。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"extremely unpleasant or bad","cn":"很坏的﹐糟透的"},{"en":"evil or immoral","cn":"可耻的﹔邪恶的"}]},"vocab":{"pos":"adj","senses":[{"en":"Surely only an evil person could be so vile as to have made you so angry. Vile is something or someone so morally wrong or offensive as to be thoroughly disgusting."}]},"media":{"uk":"media/ldoce/hwd/bre/5/vile0205.mp3","us":"media/ldoce/hwd/ame/1/vial.mp3"},"examples":[{"en":"The weather was really vile most of the time.","cn":"天气大部分时间都糟糕得很。"},{"en":"the vile practice of taking hostages","cn":"扣押人质的卑劣行径"}],"oxford":{"phon":"vaɪl","pos":"adjective","senses":[{"en":"extremely unpleasant or bad","cn":"糟糕透顶的；可恶的；极坏的","lab":"informal","ex":{"en":"There was a vile smell coming from the locked room.","cn":"从上锁的房门后传出令人恶心的气味。"}},{"en":"morally bad; completely unacceptable","cn":"邪恶的；令人完全不能接受的","lab":"formal","ex":{"en":"the vile practice of taking hostages","cn":"扣押人质的卑劣行径"}}]}},"victoria":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"a large railway station in central London, from which trains go to various parts of southeast England","cn":""},{"en":"the capital city of the Canadian province of British Columbia","cn":""},{"en":"a state in southeast Australia, which has a lot of industry. Capital: Melbourne.","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/0/p028-000012586.mp3","us":"media/ldoce/hwd/ame/0/victoria1.mp3"},"oxford":{"phon":"vɪkˈtɔːriə","pos":"","senses":[{"en":"a state in south-eastern Australia. The capital is Melbourne.","cn":"维多利亚（澳大利亚东南部的州，首府墨尔本）"},{"en":"the capital city of the Canadian province of British Columbia, a port at the southern tip of Vancouver Island","cn":"维多利亚（加拿大不列颠哥伦比亚省首府，温哥华岛南端的港口）"},{"en":"a major train station in London for trains to and from the south of England. It also has a station on the London Underground.","cn":"维多利亚：伦敦的主要火车站，往返于英格兰南部。它还在伦敦地铁上有一个车站。"},{"en":"a first name for girls","cn":"维多利亚（女子名）"}]}},"visa":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（护照的）签证","en":"A visa is an official document, or a stamp put in your passport, which allows you to enter or leave a particular country.","ex":{"en":"His visitor's visa expired.","cn":"他的访问签证过期了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an official mark put on your passport that gives you permission to temporarily enter or leave a foreign country 〔","cn":"护照上的〕签证"}]},"vocab":{"pos":"n v","senses":[{"en":"A visa is a permit to enter a specific country. Without a visa , you might not be able to travel where you want."}]},"collocations":{"phrases":["ADJ. entry, exit, transit | student, tourist, travel","VERB + VISA get, obtain I obtained a visa after hours of waiting at the embassy. | extend, renew | give sb, grant (sb), issue, issue sb (wit","VISA + VERB expire Her visa expired six months ago.","VISA + NOUN regulations, requirements, restrictions | application","PREP. on a ~ She entered the country on a student visa. | ~ for Do you need a visa for Egypt?"]},"media":{"uk":"media/ldoce/hwd/bre/3/visa0205.mp3","us":"media/ldoce/hwd/ame/9/visa1.mp3"},"examples":[{"en":"an entry/tourist/transit/exit visa","cn":"入境/旅游/过境/出境签证"},{"en":"to apply for a visa","cn":"申请签证"}],"oxford":{"phon":"ˈviːzə","pos":"noun","senses":[{"en":"a stamp or mark put in your passport by officials of a foreign country that gives you permission to enter, pass through or leave their country","cn":"（护照的）签证","ex":{"en":"to apply for a visa","cn":"申请签证"}}]}},"vivacity":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"活力;生气;魅力","en":"If you say that someone has vivacity, you mean that they are lively, exciting, and attractive.","ex":{"en":"...her exceptional vitality, vivacity and wit.","cn":"她超出常人的活力、魅力和才智"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"cheerful and active","cn":""},{"en":"a woman or girl who is vivacious has a lot of energy and a happy and attractive manner","cn":""},{"en":"full of interest and energy, especially when talking to someone","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"If someone says you're full of vivacity , that means you have high spirits and are full of life. Your vivacity makes you a great comedic actor because you attack the stage with endless energy."}]},"media":{"uk":"media/ldoce/hwd/bre/9/vivacious0205.mp3","us":"media/ldoce/hwd/ame/3/vivacious.mp3"},"examples":[{"en":"He was charmed by her beauty and vivacity.","cn":"他被她的美丽与活泼迷住了。"}],"oxford":{"phon":"vɪˈvæsəti","pos":"noun","senses":[{"en":"the quality of being lively and attractive","cn":"活泼；生气勃勃","ex":{"en":"He was charmed by her beauty and vivacity.","cn":"他被她的美丽与活泼迷住了。"}}]}},"victorian":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（英国）维多利亚（女王）时代的","en":"Victorian means belonging to, connected with, or typical of Britain in the middle and last parts of the 19th century, when Victoria was Queen.","ex":{"en":"We have a lovely old Victorian house.","cn":"我们有一栋漂亮的维多利亚时代的老房子。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（尤指对良好行为的评判标准和道德观）有维多利亚时代特点的，传统的","en":"You can use Victorian to describe people who have old-fashioned attitudes, especially about good behaviour and morals.","ex":{"en":"Victorian values are much misunderstood","cn":"维多利亚时代的价值观受到了严重误解。"}},{"pos":"N-COUNT 可数名词","cn":"（英国）维多利亚(女王）时代的人","en":"The Victorians were the British people who lived in the time of Queen Victoria."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"relating to or coming from the period from 1837–1901 when Victoria was Queen of England","cn":"英国维多利亚(女王)时代的"},{"en":"morally strict in a way that was typical in the time of Queen Victoria 〔","cn":"道德标准〕维多利亚(女王)时代特有的"},{"en":"an English person living in the period when Queen Victoria ruled","cn":"维多利亚(女王)时代的英国人"}]},"vocab":{"pos":"adj","senses":[{"en":"Someone who's victorian is particularly prudish or prissy. Your victorian math teacher might demand complete silence and expect to be addressed as \"Sir.\""}]},"media":{"uk":"media/ldoce/hwd/bre/a/victorian_n0205.mp3","us":"media/ldoce/hwd/ame/7/victorian1.mp3"},"examples":[{"en":"She advocated a return to Victorian values (= hard work, pride in your country, etc.).","cn":"她提倡恢复维多利亚时代的价值观念。"},{"en":"Victorian attitudes to sex (= being easily shocked by sexual matters)","cn":"维多利亚时代的性爱观"}],"oxford":{"phon":"vɪkˈtɔːriən","pos":"adjective","senses":[{"en":"connected with the period from 1837 to 1901 when Queen Victoria was queen in the UK","cn":"（英国）维多利亚女王时代（1837–1901 年）的","ex":{"en":"Victorian architecture","cn":"维多利亚女王时代的建筑"}},{"en":"having the attitudes that were typical of society during Queen Victoria’s reign","cn":"持维多利亚时代观点的","ex":{"en":"Victorian attitudes to sex (= being easily shocked by sexual matters)","cn":"维多利亚时代的性爱观"}},{"en":"a British person who was alive during the period from 1837 to 1901, when Queen Victoria was queen","cn":"维多利亚时代的英国人","pos":"noun"}]}},"viscera":{"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"内脏;脏腑","en":"Viscera are the large organs inside the body, such as the heart, liver, and stomach."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the large organs inside your body, such as your heart, lungs, and stomach","cn":"内脏﹐脏腑〔如心﹑肺﹑胃等〕"}]},"vocab":{"pos":"n","senses":[{"en":"If someone calls you a gutless coward, he's telling you that you lack both courage and viscera . Your viscera are your innards or your guts. In popular usage the term refers to the intestines, but technically it includes all soft internal organs."}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41viscera.mp3","us":"media/ldoce/hwd/ame/9/viscera.mp3"},"oxford":{"phon":"ˈvɪsərə","pos":"noun","senses":[{"en":"the large organs inside the body, especially the intestines","cn":"内脏；脏器；（尤指）肠"}]}},"vigour":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"体力;精力;活力","en":"Vigour is physical or mental energy and enthusiasm.","ex":{"en":"His body lacks the bounce and vigour of a normal two-year-old","cn":"他缺乏一个正常两岁儿童应具备的弹跳力与活力。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the physical and mental strength that allows you to do things","cn":""},{"en":"physical and mental energy, determination, and strength","cn":""},{"en":"an energetic determination to get things done without delay","cn":""}]},"collocations":{"phrases":["ADJ. added, increased, increasing | fresh, new, renewed He returned to work with a sense of renewed vigour after his holiday. | extraordinar","VERB + VIGOUR pursue/tackle sth with The government gave assurances that the enquiry would be pursued with vigour.","PREP. with ~","PHRASES full of vigour She was a wonderful, bubbly girl, full of vigour. | vim and vigour He set to his task with renewed vim and vigour. | "]},"media":{"uk":"media/ldoce/hwd/bre/6/vigour0205.mp3","us":"media/ldoce/hwd/ame/6/vigor.mp3"},"examples":[{"en":"He worked with renewed vigour and determination.","cn":"他将重燃起来的活力和热情投入到工作中。"},{"en":"He began working with renewed vigour .","cn":"他以更加旺盛的精力开始工作。"}],"oxford":{"phon":"ˈvɪɡə(r)","pos":"noun","senses":[{"en":"energy, force or enthusiasm","cn":"精力；力量；活力；热情","ex":{"en":"He worked with renewed vigour and determination.","cn":"他将重燃起来的活力和热情投入到工作中。"}}]}},"virginal":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"处女般的;贞洁的;纯真的","en":"If you describe someone as virginal, you mean that they look young and innocent, as if they have had no experience of sex.","ex":{"en":"Somehow she'd always been a child in his mind, pure and virginal","cn":"不知何故，她在他心里一直是个天真无邪的孩子。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"未使用过的;未玷污的","en":"Something that is virginal looks new and clean, as if it has not been used or spoiled.","ex":{"en":"...abandoning worn-out land to cultivate virginal pasture.","cn":"放弃使用过度的土地转而开发新的牧场"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"like a virgin","cn":"处女（般）的"}]},"media":{"uk":"media/ldoce/hwd/bre/9/virginal0205.mp3","us":"media/ldoce/hwd/ame/9/laadvirginal.mp3"},"examples":[{"en":"She was dressed in virginal white.","cn":"她穿了一身洁白无瑕的衣服。"}],"oxford":{"phon":"ˈvɜːdʒɪnl","pos":"adjective","senses":[{"en":"of or like a virgin; pure and innocent","cn":"处女（般）的；童贞的；贞洁的；纯真的","ex":{"en":"She was dressed in virginal white.","cn":"她穿了一身洁白无瑕的衣服。"}}]}},"viscosity":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（液体的）黏性，黏稠度","en":"Viscosity is the quality that some liquids have of being thick and sticky.","ex":{"en":"...the viscosity of the paint.","cn":"油漆的黏稠度"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a viscous liquid is thick and sticky and does not flow easily","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Viscosity is the thickness of a liquid. Water flows easily. Honey does not — that's why it has greater viscosity than water."}]},"media":{"uk":"media/ldoce/hwd/bre/8/viscous0205.mp3","us":"media/ldoce/hwd/ame/e/viscous.mp3"},"examples":[{"en":"As the liquid cools, it becomes viscous.","cn":""}],"oxford":{"phon":"vɪˈskɒsəti","pos":"noun","senses":[{"en":"the quality in a liquid of being thick and sticky; the quality of not flowing freely","cn":"（液体的）黏性；粘度"}]}},"vigilante":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（自发组成的）治安维持会会员;义务警察","en":"Vigilantes are people who organize themselves into an unofficial group to protect their community and to catch and punish criminals.","ex":{"en":"The vigilantes dragged the men out.","cn":"治安员们把那些人揪了出来。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who illegally punishes criminals and tries to prevent crime, usually because they think the police are not doing this effectively","cn":"民间护法者﹐义务警察〔指因认为警方办事不力而私自非法惩治罪犯﹑试图防止犯罪的人〕"}]},"vocab":{"pos":"n","senses":[{"en":"If you’re a vigilante, you might take the law into your own hands by trying to catch or punish someone in your own way. If you wrestle jaywalkers down to the ground, you might be called a vigilante ."}]},"media":{"uk":"media/ldoce/hwd/bre/e/vigilante0205.mp3","us":"media/ldoce/hwd/ame/b/vigilante.mp3"},"oxford":{"phon":"ˌvɪdʒɪˈlænti","pos":"noun","senses":[{"en":"a member of a group of people who try to prevent crime or punish criminals in their community, especially because they think the police are not doing this","cn":"（尤指认为警方不力而自发组织的）治安会会员","ex":{"en":"vigilantes patrolling the streets","cn":"民警在街上巡逻"}}]}},"violation":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an illegal action for which you can be punished","cn":""},{"en":"an illegal action, especially one that breaks a law that protects someone's rights","cn":""},{"en":"an action that breaks a law or agreement, especially one that has been agreed by several different countries - use this about a serious illegal action","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Anytime a person crosses a boundary — a legal boundary, a moral boundary, a physical boundary, or a binding business deal — that's a violation . When a burglar picks the lock on your door, that's a violation of your property."}]},"collocations":{"phrases":["ADJ. blatant, clear, flagrant The attack on civilians is a flagrant violation of the peace agreement. | grave, gross, major, massive, seriou","VERB + VIOLATION commit The army was accused of committing violations against the accord. | be, constitute This action constitutes a violati","PREP. in ~ of There is plenty of evidence that her actions were in violation of an earlier contract. | ~ against violations against minimum "]},"media":{"uk":"media/ldoce/hwd/bre/f/violation0205.mp3","us":"media/ldoce/hwd/ame/2/laadviolation.mp3"},"examples":[{"en":"They were in open violation of the treaty.","cn":"他们公然违反条约。"},{"en":"gross violations of human rights","cn":"对人权的粗暴践踏"}],"oxford":{"phon":"ˌvaɪəˈleɪʃn","pos":"noun","senses":[{"en":"the act of going against or refusing to obey a law, an agreement, etc.","cn":"（对法律、协议等的）违反，违犯，违背","lab":"formal","ex":{"en":"They were in open violation of the treaty.","cn":"他们公然违反条约。"}},{"en":"the act of not respecting somebody's rights, peace, privacy, etc.","cn":"（对隐私等的）侵犯，搅扰","lab":"formal","ex":{"en":"gross violations of human rights","cn":"对人权的粗暴践踏"}},{"en":"the act of damaging or destroying a holy or special place","cn":"（对神圣之地的）亵渎，污损","ex":{"en":"This was a violation of a sacred space.","cn":"这是对圣地的亵渎。"}},{"en":"the act of forcing somebody to have sex","cn":"强奸；奸污","lab":"literary or old-fashioned"}]}},"vintner":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"葡萄酒商","en":"A vintner is someone whose job is to buy and sell wine."},{"pos":"N-COUNT 可数名词","cn":"葡萄酒酿制者","en":"A vintner is someone who grows grapes and makes wine."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who buys and sells wines","cn":"葡萄酒商"}]},"vocab":{"pos":"n","senses":[{"en":"A vintner is a wine merchant — the very person you'd visit if you wanted to buy a nice Merlot or Cabernet Sauvignon."}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41vintner.mp3","us":"media/ldoce/hwd/ame/6/vintner.mp3"},"oxford":{"phon":"ˈvɪntnə(r)","pos":"noun","senses":[{"en":"a person whose business is buying and selling wines or a person who grows grapes and makes wine","cn":"葡萄酒商；葡萄酒酿制者"}]}},"vinaigrette":{"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"色拉调味汁（用油、醋、盐、胡椒、香草等混合调成)","en":"Vinaigrette is a dressing made by mixing oil, vinegar, salt, pepper, and herbs, which is put on salad."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a mixture of oil, vinegar , salt, and pepper that you put on a salad 〔","cn":"油﹑醋﹑盐﹑胡椒混合成的〕沙拉调味汁"}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41vinaigrette.mp3","us":"media/ldoce/hwd/ame/5/vinaigrette.mp3"},"oxford":{"phon":"ˌvɪnɪˈɡret","pos":"noun","senses":[{"en":"a mixture of oil, vinegar and various herbs, etc., added to a salad","cn":"色拉调味汁（用油、醋和各种香草等混合而成）"}]}},"vituperation":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"责骂;辱骂;谩骂;咒骂","en":"Vituperation is language that is full of hate, anger, or insults."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"angry and cruel criticism","cn":"谩骂﹐咒骂﹐辱骂"}]},"vocab":{"pos":"n","senses":[{"en":"Vituperation is a noun that refers to critical, abusive language. It's always a messy scene when a political debate slips into vituperation ."}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41vituperation.mp3","us":"media/ldoce/hwd/ame/f/vituperation.mp3"},"examples":[{"en":"a vituperative attack","cn":"谩骂式的攻击"}],"oxford":{"phon":"vɪˌtjuːpəˈreɪʃn","pos":"noun","senses":[{"en":"cruel and angry criticism","cn":"辱骂；斥责；责骂","ex":{"en":"She was unprepared for the flood of vituperation which descended on her from her critics.","cn":"她对批评者如潮水般的谩骂毫无准备。"}}]}},"vicarious":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"从他人经验中获得的;间接感受到的","en":"A vicarious pleasure or feeling is experienced by watching, listening to, or reading about other people doing something, rather than by doing it yourself.","ex":{"en":"She invents fantasy lives for her own vicarious pleasure","cn":"她幻想过着各种奇妙的生活，从想入非非中获得乐趣。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if you hear about something second-hand , you hear about it from another person or by reading about it, for example in a newspaper","cn":""},{"en":"use this when describing something that you do not do, learn, or experience yourself, but through someone else","cn":""},{"en":"pleasure etc experienced by watching or reading about someone else doing something, rather than by doing it yourself","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If something is vicarious , it delivers a feeling or experience from someone else. If your child becomes a big star, you might have a vicarious experience of celebrity."}]},"media":{"uk":"media/ldoce/hwd/bre/1/vicarious0205.mp3","us":"media/ldoce/hwd/ame/5/vicarious.mp3"},"examples":[{"en":"He got a vicarious thrill out of watching his son score the winning goal.","cn":"他看着儿子射入获胜的一球，也同样感到欣喜若狂。"}],"oxford":{"phon":"vɪˈkeəriəs","pos":"adjective","senses":[{"en":"felt or experienced by watching or reading about somebody else doing something, rather than by doing it yourself","cn":"间接感受到的","ex":{"en":"He got a vicarious thrill out of watching his son score the winning goal.","cn":"他看着儿子射入制胜球，同样感到欣喜若狂。"}}]}},"vitriolic":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（言行）恶意的，刻薄的，尖刻的","en":"If you describe someone's language or behaviour as vitriolic, you disapprove of it because it is full of bitterness and hate, and so causes a lot of distress and pain.","ex":{"en":"There was a vicious and vitriolic attack on him in one of the Sunday newspapers two weeks ago.","cn":"两周前一份周日报纸刊登了一篇对他进行尖酸恶毒攻击的文章。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"vitriolic language, writing etc is very cruel and angry towards someone 〔","cn":"言语〕尖刻的﹐辛辣的"}]},"vocab":{"pos":"1 adj 2 adj","senses":[{"en":"Mean, nasty, and caustic as the worst acid, vitriolic words can hurt feelings, break hearts, and even lead to violence."}]},"media":{"uk":"media/ldoce/hwd/bre/c/vitriolic0205.mp3","us":"media/ldoce/hwd/ame/0/vitriolic.mp3"},"examples":[{"en":"The newspaper launched a vitriolic attack on the president.","cn":"这家报纸对总统发起了一场恶意的攻击。"},{"en":"vitriolic remarks","cn":"刻薄的言辞"}],"oxford":{"phon":"ˌvɪtriˈɒlɪk","pos":"adjective","senses":[{"en":"full of anger and hate","cn":"愤怒的；恶意的；尖酸刻薄的","ex":{"en":"The newspaper launched a vitriolic attack on the president.","cn":"这家报纸对总统发起了一场恶意的攻击。"}}]}},"vituperative":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"责骂的;辱骂的;谩骂的","en":"Vituperative remarks are full of hate, anger, or insults.","ex":{"en":"He is often the victim of vituperative remarks concerning his wealth.","cn":"他经常因为富有而受到辱骂。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"full of angry and cruel criticism","cn":"谩骂的﹐充满辱骂的"}]},"vocab":{"pos":"adj","senses":[{"en":"Use the adjective vituperative to describe criticism that's so sharp it hurts. A vituperative review of a movie would make the director bitter for months."}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41vituperative.mp3","us":"media/ldoce/hwd/ame/1/ld41vituperative.mp3"},"examples":[{"en":"a vituperative attack","cn":"谩骂式的攻击"},{"en":"vituperative comments","cn":"谩骂性的评论"}],"oxford":{"phon":"vɪˈtjuːpərətɪv","pos":"adjective","senses":[{"en":"criticizing in a cruel and angry way","cn":"恶毒","ex":{"en":"a vituperative attack","cn":"一顿痛骂"}}]}},"virulent":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"恶毒的;狠毒的;充满敌意的","en":"Virulent feelings or actions are extremely bitter and hostile.","ex":{"en":"Now he faces virulent attacks from the Italian media","cn":"现在他面临着意大利媒体的恶毒攻击。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"致命的;剧毒的","en":"A virulent disease or poison is extremely powerful and dangerous.","ex":{"en":"A very virulent form of the disease appeared in Belgium.","cn":"比利时出现了这种疾病的一种极其危险的变体。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a poison, disease etc that is virulent is very dangerous and affects people very quickly 〔","cn":"毒物〕剧毒的﹔〔疾病〕迅速致命的"},{"en":"full of hatred for something, or expressing this in a strong way – used to show disapproval","cn":"充满仇恨的﹐刻毒的﹐恶毒的〔含贬义〕"}]},"vocab":{"pos":"adj","senses":[{"en":"A virulent disease is one that's infectious, spreading and making lots of people sick, while a virulent rant is just a verbal attack, causing sickness of the emotional kind. Either way, something virulent puts a strain on the people who get it."}]},"media":{"uk":"media/ldoce/hwd/bre/d/virulent0205.mp3","us":"media/ldoce/hwd/ame/a/virulent.mp3"},"examples":[{"en":"virulent nationalism","cn":"不共戴天的民族主义"},{"en":"virulent criticism","cn":"恶意的批评"}],"oxford":{"phon":"ˈvɪrələnt","pos":"adjective","senses":[{"en":"extremely dangerous or harmful and quick to have an effect","cn":"致命的；恶性的；剧毒的","ex":{"en":"a virulent form of influenza","cn":"一种致命的流感"}},{"en":"showing strong negative and bitter feelings","cn":"狠毒的；恶毒的；不共戴天的","lab":"formal","ex":{"en":"virulent criticism","cn":"恶意的批评"}}]}},"vigilant":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"警惕的;警觉的；警戒的","en":"Someone who is vigilant gives careful attention to a particular problem or situation and concentrates on noticing any danger or trouble that there might be.","ex":{"en":"He warned the public to be vigilant and report anything suspicious","cn":"他警告公众要提高警惕，遇到任何可疑情况都要报告。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is careful tries to avoid danger, risks, or accidents","cn":""},{"en":"someone who is cautious does not like taking risks and is always very careful to avoid them","cn":""},{"en":"if you do something with care or with caution , you do it carefully in order to avoid accidents","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Use vigilant to describe someone who keeps awake and alert in order to avoid danger or problems. When taking the subway, be vigilant about your wallet––always know where it is, or someone might steal it from you."}]},"collocations":{"phrases":["VERBS be, keep, remain, stay | become","ADV. especially, extra, extremely, particularly, very | constantly, ever The organization is ever vigilant for threats to the habitats of bi","PREP. about Be extra vigilant about what you eat or drink. | against You need to be vigilant against garden pests."]},"media":{"uk":"media/ldoce/hwd/bre/3/vigilant0205.mp3","us":"media/ldoce/hwd/ame/8/vigilant.mp3"},"examples":[{"en":"A pilot must remain vigilant at all times.","cn":"飞行员必须随时保持警惕。"},{"en":"She stressed the need for constant vigilance.","cn":"她强调必须时常保持警惕。"}],"oxford":{"phon":"ˈvɪdʒɪlənt","pos":"adjective","senses":[{"en":"very careful to notice any signs of danger or trouble","cn":"警觉的；警惕的；警戒的；谨慎的","ex":{"en":"A pilot must remain vigilant at all times.","cn":"飞行员必须随时保持警惕。"}}]}},"vitiate":{"collins":{"senses":[{"pos":"VERB 动词","cn":"削弱…的效能;损害;使失效;使变质","en":"If something is vitiated, its effectiveness is spoiled or weakened.","ex":{"en":"Strategic policy during the War was vitiated because of a sharp division between 'easterners' and 'westerners'","cn":"由于“东方人”和“西方人”之间存在巨大的分歧，战争期间的战略方针没有得到切实的执行。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make something less effective or spoil it","cn":"削弱〔某物〕的效能﹔破坏﹐损害"}]},"vocab":{"pos":"v","senses":[{"en":"As some sneaky five-year-olds know, crossing one’s fingers while making a promise is an effective way to vitiate , or destroy the validity of, an agreement."}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41vitiate.mp3","us":"media/ldoce/hwd/ame/0/vitiate.mp3"},"oxford":{"phon":"ˈvɪʃieɪt","pos":"verb","senses":[{"en":"to destroy or reduce the effect of something","cn":"使失效；削弱效用","ex":{"en":"The ‘yes’ vote was vitiated by the low turnout in the election.","cn":"由于选举投票率低，“赞成”票被削弱。"}}]}},"vindictive":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"想复仇的;报复性的;怀恨在心的","en":"If you say that someone is vindictive, you are critical of them because they deliberately try to upset or cause trouble for someone who they think has done them harm.","ex":{"en":"How can you be so vindictive?","cn":"你的报复心怎么那么强？"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"deliberately cruel and unkind to someone because you really want to upset them and enjoy doing so","cn":""},{"en":"deliberately nasty to someone in order to hurt or upset them, especially because you are jealous of them or are angry with them","cn":""},{"en":"a feeling of wanting to hurt or upset other people by saying or doing cruel things, especially if you feel jealous or think you have been unfairly treated","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"It is no fun hanging out with vindictive people, who are forever out to get back at people they think have hurt them. If you forget to say hello to them one day in the hall, they will carry a grudge against you into next week."}]},"media":{"uk":"media/ldoce/hwd/bre/9/vindictive0205.mp3","us":"media/ldoce/hwd/ame/f/vindictive.mp3"},"examples":[{"en":"He accused her of being vindictive.","cn":"他指责她存心报复。"},{"en":"a vindictive comment","cn":"报复性的言论"}],"oxford":{"phon":"vɪnˈdɪktɪv","pos":"adjective","senses":[{"en":"showing a strong and unreasonable desire to harm or upset somebody because you think that they have harmed you","cn":"想复仇的；报复性的；怀恨的","ex":{"en":"He accused her of being vindictive.","cn":"他指责她存心报复。"}}]}},"vibe":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"感应；气氛;环境","en":"Vibes are the good or bad atmosphere that you sense with a person or in a place.","ex":{"en":"Sorry, Chris, but I have bad vibes about this guy","cn":"对不起，克里斯，可我对这个家伙很反感。"}},{"pos":"N-PLURAL 复数名词","cn":"同vibraphone","en":"Vibes are the same as a vibraphone .","ex":{"en":"...a variety of other instruments, including vibes, cello, bass, accordion and clarinet.","cn":"包括电颤琴、大提琴、低音吉他、手风琴和单簧管在内的其他多种乐器"}}]}},"vienna":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"the capital city of Austria, famous as a centre for music since the 18th century, and the home of many famous composer s , including mozart and beethoven .","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/4/p028-000012601.mp3","us":"media/ldoce/hwd/ame/4/p028-000012601.mp3"}},"vigilance":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"if you do something with care, you are careful to avoid damage, mistakes etc","cn":""},{"en":"care to avoid danger or risks, or care about trusting information that might not be true","cn":""},{"en":"a sensible and careful attitude that makes you avoid unnecessary risks – a rather formal use","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Vigilance is devoted attentiveness or watchfulness. Security guards and test proctors alike need to practice vigilance ."}]},"collocations":{"phrases":["ADJ. constant, continued, eternal | extra, increased, special You should exercise extra vigilance about locking your car properly.","VERB + VIGILANCE exercise, maintain | relax The birds cannot afford to relax their vigilance against predators. | require","PREP. ~ against vigilance against shoplifters | ~ on the part of sb Guaranteeing the safety of students requires continued vigilance on the ","PHRASES a need for vigilance"]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41vigilance.mp3","us":"media/ldoce/hwd/ame/b/vigilance.mp3"},"examples":[{"en":"She stressed the need for constant vigilance.","cn":"她强调必须时常保持警惕。"},{"en":"the need for increased police vigilance","cn":"警方加强警戒的必要性"}],"oxford":{"phon":"ˈvɪdʒɪləns","pos":"noun","senses":[{"en":"great care that is taken to notice any signs of danger or trouble","cn":"警戒；警惕","ex":{"en":"She stressed the need for constant vigilance.","cn":"她强调必须时常保持警惕。"}}]}},"viola":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"中提琴","en":"A viola is a musical instrument with four strings that is played with a bow. It is like a violin, but is slightly larger and can play lower notes."},{"pos":"N-COUNT 可数名词","cn":"堇菜属植物;三色堇","en":"Violas are small plants with white, yellow, or purple flowers."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a wooden musical instrument that you play like a violin but that is larger and has a lower sound","cn":"中提琴"},{"en":"a plant related to the violet","cn":"堇菜"}]},"media":{"uk":"media/ldoce/hwd/bre/9/brelasdeviola.mp3","us":"media/ldoce/hwd/ame/3/viola.mp3"},"examples":[{"en":"a viola player","cn":"中提琴手"}],"oxford":{"phon":"viˈəʊlə","pos":"noun","senses":[{"en":"a musical instrument with strings, that you hold under your chin and play with a bow. A viola is larger than a violin and plays lower notes.","cn":"中提琴","ex":{"en":"a viola player","cn":"中提琴手"}}]}},"virile":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"男性的;有男子气概的;阳刚的","en":"If you describe a man as virile, you mean that he has the qualities that a man is traditionally expected to have, such as strength and sexual power.","ex":{"en":"He wanted his sons to become strong, virile, and athletic like himself.","cn":"他希望他的儿子们能长得像他一样强壮、阳刚而又健美。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"强有力的;强劲的","en":"Something that is described as virile is considered to be very strong and forceful.","ex":{"en":"...Prokofiev's most virile, aggressive music.","cn":"普罗科菲耶夫的最强劲有力的音乐"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"masculine behaviour or attitudes are considered to be more typical of a man than of a woman","cn":""},{"en":"looking or behaving in a way that is typical of a man, by being strong, full of energy etc, and therefore sexually attractive","cn":""},{"en":"having the qualities that people expect and admire in a man, such as being brave and strong","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"You'll often hear the word virile referring to a manly, powerful man, because the word means having physical strength and other typical masculine qualities."}]},"media":{"uk":"media/ldoce/hwd/bre/2/virile0205.mp3","us":"media/ldoce/hwd/ame/a/virile.mp3"},"examples":[{"en":"a virile performance","cn":"雄壮的演奏"},{"en":"virile athleticism","cn":"雄健的体魄"}],"oxford":{"phon":"ˈvɪraɪl","pos":"adjective","senses":[{"en":"strong and full of energy, especially sexual energy","cn":"强壮的；精力充沛的；（尤指）性机能强的"},{"en":"having or showing the strength and energy that is considered typical of men","cn":"有阳刚之气的；有男子气概的；雄浑的","ex":{"en":"a virile performance","cn":"雄壮的演奏"}}]}},"vigorous":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（体育活动）剧烈的，强度大的，强劲的","en":"Vigorous physical activities involve using a lot of energy, usually to do short and repeated actions.","ex":{"en":"Very vigorous exercise can increase the risk of heart attacks","cn":"运动太过剧烈会增大心脏病发作的风险。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"活跃的;积极的;热烈的","en":"A vigorous person does things with great energy and enthusiasm. A vigorous campaign or activity is done with great energy and enthusiasm.","ex":{"en":"Sir Robert was a strong and vigorous politician.","cn":"罗伯特爵士是位坚定而又活跃的政治家。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"精力旺盛的;充满活力的","en":"A vigorous person is strong and healthy and full of energy.","ex":{"en":"He was a vigorous, handsome young man.","cn":"他是个精力充沛、年轻帅气的小伙子。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"involving a lot of physical activity","cn":""},{"en":"using a lot of energy and strength","cn":""},{"en":"work that always involves the same high level of effort","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Anything vigorous is done with force and energy. Vigorous exercise makes you sweat, and a vigorous denial makes someone else sweat."}]},"collocations":{"phrases":["VERBS be | become","ADV. extremely, very leading a very vigorous campaign to get the chairman removed | quite taking some quite vigorous exercise | enough, suff","PREP. in The group is not vigorous enough in its opposition to the proposals."]},"media":{"uk":"media/ldoce/hwd/bre/f/vigorous0205.mp3","us":"media/ldoce/hwd/ame/c/laadvigorous.mp3"},"examples":[{"en":"This plant is a vigorous grower.","cn":"这种植物生长起来茂盛茁壮。"},{"en":"Take vigorous exercise for several hours a week.","cn":"每周做几个小时剧烈运动。"}],"oxford":{"phon":"ˈvɪɡərəs","pos":"adjective","senses":[{"en":"very active, determined or full of energy","cn":"充满活力的；果断的；精力充沛的","ex":{"en":"They conducted a vigorous campaign against tax fraud.","cn":"他们发起了坚决打击骗税的运动。"}},{"en":"strong and healthy","cn":"强壮的；强健的","ex":{"en":"a vigorous young man","cn":"身强力壮的年轻人"}}]}},"vibraphone":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"电颤琴","en":"A vibraphone is an electronic musical instrument which consists of a set of metal bars in a frame. When you hit the bars they produce ringing notes that last for some time."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an electronic musical instrument that consists of metal bars that you hit with special sticks to produce a sound","cn":"颤音琴〔一种打击乐器〕"}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41vibraphone.mp3","us":"media/ldoce/hwd/ame/d/vibraphone.mp3"},"oxford":{"phon":"ˈvaɪbrəfəʊn","pos":"noun","senses":[{"en":"a musical instrument used especially in jazz that has two rows of metal bars that you hit, and a motor that makes them vibrate","cn":"颤音琴（常用于爵士乐）"}]}},"virginity":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the act of having sex with someone","cn":""},{"en":"if two people make love , they have sex because they like or love each other","cn":""},{"en":"to have sex with someone you are not married to, especially regularly and over a period of time","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Virginity is the condition of never having had sex."}]},"collocations":{"phrases":["VERB + VIRGINITY lose"]},"media":{"uk":"media/ldoce/hwd/bre/2/virginity0205.mp3","us":"media/ldoce/hwd/ame/9/virginity.mp3"},"examples":[{"en":"He lost his virginity (= had sex for the first time) when he was 18.","cn":"他在 18 岁时失去童贞。"}],"oxford":{"phon":"vəˈdʒɪnəti","pos":"noun","senses":[{"en":"the state of being a virgin","cn":"处女状态；童贞；原始状态","ex":{"en":"He lost his virginity (= had sex for the first time) when he was 18.","cn":"他在 18 岁时失去童贞。"}}]}},"vinyl":{"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"乙烯基;乙烯基塑料","en":"Vinyl is a strong plastic used for making things such as floor coverings and furniture.","ex":{"en":"...a modern vinyl floor covering.","cn":"一种以乙烯基为原料的现代地板革"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（尤指区别于磁带和光盘的）塑料唱片，黑胶唱片","en":"You can use vinyl to refer to records, especially in contrast to cassettes or compact discs.","ex":{"en":"This compilation was first issued on vinyl in 1984.","cn":"这张精选集在1984年首次以唱片形式发行。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a type of strong plastic","cn":"乙烯基(塑料)"},{"en":"records that are played on a record player – used especially when comparing them to CD s","cn":"黑胶唱片"}]},"media":{"uk":"media/ldoce/hwd/bre/6/vinyl0205.mp3","us":"media/ldoce/hwd/ame/f/vinyl.mp3"},"examples":[{"en":"My dad had to buy CDs of all the albums he already owned on vinyl.","cn":"我爸爸就是要买他已有的所有黑胶唱片的 CD 版。"}],"oxford":{"phon":"ˈvaɪnl","pos":"noun","senses":[{"en":"a strong plastic that can bend easily, used for covering walls, floors and furniture, and for making book covers and, especially in the past, records","cn":"乙烯基；乙烯基塑料"},{"en":"records made of vinyl, in contrast to CDs","cn":"乙烯基唱片；黑胶唱片","ex":{"en":"My dad still has all his old albums on vinyl.","cn":"我爸爸还保留着他所有旧专辑的黑胶唱片。"}}]}},"virtuoso":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"大师;专家;（尤指）演奏家","en":"A virtuoso is someone who is extremely good at something, especially at playing a musical instrument.","ex":{"en":"He was gaining a reputation as a remarkable virtuoso.","cn":"作为一位技艺非凡的大师，他声誉日隆。"}},{"pos":"ADJ 形容词","cn":"（演出或展示）杰出的，技艺精湛的","en":"A virtuoso performance or display shows great skill.","ex":{"en":"England's football fans were hoping for a virtuoso performance against Cameroon.","cn":"英格兰队的球迷期待着该队与喀麦隆队能够上演一场精彩对决。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who has a lot of knowledge about something or skill at doing something","cn":""},{"en":"an expert who has studied a particular medical or technical subject for a long time and knows much more about it than other people","cn":""},{"en":"an expert whose knowledge and opinions are greatly respected","cn":""}]},"vocab":{"pos":"n adj","senses":[{"en":"A virtuoso is an incredibly talented musician. You can also be a virtuoso in non-musical fields."}]},"media":{"uk":"media/ldoce/hwd/bre/7/virtuoso0205.mp3","us":"media/ldoce/hwd/ame/4/virtuoso.mp3"},"examples":[{"en":"a virtuoso performance","cn":"技艺精湛的表演"},{"en":"a piano virtuoso","cn":"钢琴演奏家"}],"oxford":{"phon":"ˌvɜːtʃuˈəʊsəʊ","pos":"noun","senses":[{"en":"a person who shows very great skill at doing something, especially playing a musical instrument","cn":"技艺超群的人；（尤指）演奏家","ex":{"en":"a piano virtuoso","cn":"钢琴演奏家"}},{"en":"showing extremely great skill","cn":"技艺精湛的；技巧超群的","ex":{"en":"Kane treated us to a virtuoso performance against Chelsea this afternoon.","cn":"今天下午对阵切尔西的比赛中，凯恩为我们带来了一场精彩的表演。"},"pos":"adjective"}]}},"virulence":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"恶毒;狠毒;敌意","en":"Virulence is great bitterness and hostility.","ex":{"en":"The virulence of the café owner's anger had appalled her.","cn":"咖啡店老板怒气冲天，充满敌意，把她吓坏了。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"毒力;毒性;致命性","en":"The virulence of a disease or poison is its ability to harm or kill people or animals.","ex":{"en":"Medical authorities were baffled, both as to its causes and its virulence.","cn":"医疗当局对其病因及有多致命都还不甚了解。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a poison, disease etc that is virulent is very dangerous and affects people very quickly","cn":""},{"en":"full of hatred for something, or expressing this in a strong way – used to show disapproval","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Virulence is a harmful quality possessed by microorganisms that can cause disease. You can also use the noun virulence to describe someone's malicious actions."}]},"media":{"uk":"media/ldoce/hwd/bre/d/virulent0205.mp3","us":"media/ldoce/hwd/ame/a/virulent.mp3"},"examples":[{"en":"a particularly virulent form of influenza","cn":""}],"oxford":{"phon":"ˈvɪrələns","pos":"noun","senses":[{"en":"the degree to which a disease or poison is dangerous or harmful and quick to have an effect","cn":"（病毒等的）毒性；毒力","ex":{"en":"the virulence of the virus strain","cn":"病毒株的毒力"}},{"en":"the fact of showing strong negative and bitter feelings","cn":"恶意；恶毒；刻毒","lab":"formal","ex":{"en":"the virulence of the attacks on her in the press","cn":"媒体对她的猛烈攻击"}}]}},"vilify":{"collins":{"senses":[{"pos":"VERB 动词","cn":"诬蔑;诋毁;诽谤;中伤","en":"If you are vilified by someone, they say or write very unpleasant things about you, so that people will have a low opinion of you.","ex":{"en":"The agency has been vilified by some doctors for being unnecessarily slow to approve life-saving drugs","cn":"该机构因对救生药物的审批速度太慢而备受一些医生的诟病。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to say or write bad things about someone or something","cn":"诬蔑﹐中伤﹐诽谤"}]},"vocab":{"pos":"v","senses":[{"en":"To vilify someone is to spread nasty stories about them, whether true or not."}]},"media":{"uk":"media/ldoce/hwd/bre/2/vilify0205.mp3","us":"media/ldoce/hwd/ame/8/vilify.mp3"},"examples":[{"en":"the vilification of single parents by right-wing politicians","cn":"右翼政客对单亲父母的诋毁"},{"en":"Johnson was vilified in the press for refusing to resign.","cn":"约翰逊因拒绝辞职而在报刊上遭到诋毁。"}],"oxford":{"phon":"ˈvɪlɪfaɪ","pos":"verb","senses":[{"en":"to say or write unpleasant things about somebody/something so that other people will have a low opinion of them","cn":"污蔑；诽谤；诋毁；中伤","ex":{"en":"A campaign was mounted to vilify the leaders of the organization.","cn":"发起了一场诽谤该组织领导人的运动。"}}]}},"vinegary":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有醋味的;酸的","en":"If something has a vinegary taste or smell, it tastes or smells of vinegar.","ex":{"en":"The salads taste too vinegary.","cn":"这色拉的味道太酸了。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"tasting of vinegar","cn":"酸的﹐醋味的"}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41vinegary.mp3","us":"media/ldoce/hwd/ame/5/ld41vinegary.mp3"},"examples":[{"en":"a vinegary wine","cn":"酸葡萄酒"}],"oxford":{"phon":"ˈvɪnɪɡəri","pos":"adjective","senses":[{"en":"having a taste or smell that is typical of vinegar","cn":"醋的；酸的；有醋味的","ex":{"en":"a vinegary wine","cn":"酸葡萄酒"}}]}},"vintage":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（某优质葡萄酒的）产地和年份;特定年份酿的葡萄酒","en":"The vintage of a good quality wine is the year and place that it was made before being stored to improve it. You can also use vintage to refer to the wine that was made in a certain year.","ex":{"en":"Many predict 1991 will rival the great vintage of 1965","cn":"许多人预测1991年酿制的葡萄酒可以与1965年生产的佳酿相媲美。"}},{"pos":"ADJ 形容词","cn":"（葡萄酒）优质的，上等的，佳酿的","en":"Vintage wine is good quality wine that has been stored for several years in order to improve its quality.","ex":{"en":"If you can buy only one case at auction, it should be vintage port.","cn":"如果你在拍卖会上只能买一样东西，那就应该是上等的波尔图葡萄酒。"}},{"pos":"ADJ 形容词","cn":"（汽车或飞机)老式的，古色古香的","en":"Vintage cars or aeroplanes are old but are admired because they are considered to be the best of their kind.","ex":{"en":"The museum will have a permanent exhibition of 60 vintage cars.","cn":"这个博物馆将长期展出60辆老爷车。"}},{"pos":"ADJ 形容词","cn":"最佳的;典型的;优质的","en":"You can use vintage to describe something which is the best and most typical of its kind.","ex":{"en":"At the press conference, James is on vintage form","cn":"在这次记者招待会上，詹姆斯的表现最出色。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"antique furniture, jewellery, clocks etc are old and valuable, and often beautiful to look at","cn":""},{"en":"use this about a car or a wine that is old and one of the best of its type","cn":""},{"en":"something such as a piece of furniture or a beautiful object that is old and valuable","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A vintage is the specific year that a wine was made. Different vintages are better than others."}]},"collocations":{"phrases":["ADJ. classic, fine, superb | rare","VINTAGE + NOUN champagne, claret, port, etc."]},"media":{"uk":"media/ldoce/hwd/bre/7/brelasdevintage.mp3","us":"media/ldoce/hwd/ame/c/vintage1.mp3"},"examples":[{"en":"The opera is vintage Rossini.","cn":"这部歌剧是罗西尼的最佳代表作。"},{"en":"The vintage was later than usual.","cn":"这次葡萄的收获季节比往常晚。"}],"oxford":{"phon":"ˈvɪntɪdʒ","pos":"noun","senses":[{"en":"the wine that was produced in a particular year or place; the year in which it was produced","cn":"特定年份（或地方）酿制的酒；酿造年份","ex":{"en":"the 1999 vintage","cn":"1999 年酿制的葡萄酒"}},{"en":"the period or season of gathering grapes for making wine","cn":"采摘葡萄酿酒的期间（或季节）；葡萄收获期（或季节）","g":"[usually singular]","ex":{"en":"The vintage was later than usual.","cn":"这次葡萄的收获季节比往常晚。"}},{"en":"vintage wine is of very good quality and has been stored for several years","cn":"（葡萄酒）优质的，上等的，佳酿的","pos":"adjective"},{"en":"made between 1919 and 1930 and admired for its style and interest","cn":"老式的，古典的（指 1919–1930 年间制造，车型和品味受人青睐的）","lab":"British English","ex":{"en":"a vintage rally (= for vehicles of this type)","cn":"老爷车拉力赛"},"pos":"adjective"},{"en":"typical of a period in the past and of high quality; the best work of the particular person","cn":"（过去某个时期）典型的，优质的；（某人的）最佳作品的","ex":{"en":"a collection of vintage designs","cn":"优秀设计选编"},"pos":"adjective"},{"en":"a particularly good and successful year","cn":"成绩卓著的一年；成功的一年","ex":{"en":"2008 was not a vintage year for the movies.","cn":"2008 年对电影业来说不是个好年景。"},"pos":"adjective"}]}},"vixen":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"雌狐","en":"A vixen is a female fox."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a female fox","cn":"雌狐"},{"en":"an offensive word for a woman who is bad-tempered or who fights","cn":"悍妇﹐泼妇〔冒犯性用语〕"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"A vixen is a female fox. Or it can be a woman with a temper. If you really want to insult a woman who is a little short on patience, call her a vixen . She won’t like it."}]},"media":{"uk":"media/ldoce/hwd/bre/c/vixen0205.mp3","us":"media/ldoce/hwd/ame/4/vixen.mp3"},"oxford":{"phon":"ˈvɪksn","pos":"noun","senses":[{"en":"a female fox (= a wild animal of the dog family)","cn":"雌狐"},{"en":"an offensive word for a woman who is thought to be frightening, especially one who is considered sexually attractive","cn":"悍妇，泼妇（冒犯性用语）","lab":"old-fashioned, offensive，，"}]}},"vial":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（装香水、药物等的）小瓶","en":"A vial is a very small bottle which is used to hold something such as perfume or medicine."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a very small bottle used for medicine, perfume etc 〔","cn":"装药物﹑香水等的〕小瓶"}]},"vocab":{"pos":"n","senses":[{"en":"The word vial sounds like another word, \"vile\" (making them homonyms), but they mean completely different things. A vial is just a small glass bottle that contains a chemical or drug. \"Vile\" is evil."}]},"media":{"img":["media/ldoce/img/vial.jpg"],"uk":"media/ldoce/hwd/bre/a/ld41vial.mp3","us":"media/ldoce/hwd/ame/1/vial.mp3"},"oxford":{"phon":"ˈvaɪəl","pos":"noun","senses":[{"en":"a small glass container, for medicine or perfume","cn":"管形瓶；小药瓶","ex":{"en":"a vial of pills/perfume/toilet water","cn":"一小瓶药丸／香水／花露水"}}]}},"victimize":{"collins":{"senses":[{"pos":"VERB 动词","cn":"迫害;使受害;使受苦","en":"If someone is victimized, they are deliberately treated unfairly.","ex":{"en":"He felt the students had been victimized because they'd voiced opposition to the government.","cn":"他觉得学生们受到迫害是因为他们表达了对政府的不满。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to deliberately treat a person or animal in a cruel way, especially when you are responsible for looking after them","cn":""},{"en":"to be cruel to someone who is weaker, younger, or has less authority than you","cn":""},{"en":"to treat someone in your family or someone you are responsible for in a cruel way, especially violently or sexually","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To victimize is to make someone into a victim by harming or taking advantage of them in some way. A school bully might be known to victimize other kids on the playground."}]},"media":{"uk":"media/ldoce/hwd/bre/2/victimize0205.mp3","us":"media/ldoce/hwd/ame/9/victimize.mp3"},"examples":[{"en":"For years the family had been victimized by racist neighbours.","cn":"多年来这家人因邻居怀有种族偏见而饱受欺凌。"},{"en":"The union claimed that some of its members had been victimized for taking part in the strike.","cn":"工会声称有些会员因参加罢工而受到迫害。"}],"oxford":{"phon":"ˈvɪktɪmaɪz","pos":"verb","senses":[{"en":"to make somebody suffer unfairly because you do not like them, their opinions, or something that they have done","cn":"（不正当地）使受害，使受苦","ex":{"en":"For years the family had been victimized by racist neighbours.","cn":"多年来这家人因邻居怀有种族偏见而饱受欺凌。"}}]}},"vip":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"要人;贵宾","en":"A VIP is someone who is given better treatment than ordinary people because they are famous, influential, or important. VIP is an abbreviation for (缩略=) 'very important person'.","ex":{"en":"...such VIPs as Prince Charles and Richard Nixon","cn":"查尔斯王子和理查德·尼克松这样的贵宾"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an important person has a lot of power or influence","cn":""},{"en":"a scientist, politician etc who is well-known and successful, and who usually has a lot of influence","cn":""},{"en":"important and having a lot of influence especially in politics or business","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/a/brelasdevip.mp3","us":"media/ldoce/hwd/ame/d/vip.mp3"},"examples":[{"en":"to get the VIP treatment","cn":"得到贵宾待遇"},{"en":"the VIP lounge","cn":"贵宾厅"}],"oxford":{"phon":"ˌviː aɪ ˈpiː","pos":"noun","senses":[{"en":"a famous or important person who is treated in a special way (the abbreviation for ‘Very Important Person’)","cn":"要人，贵宾（全写为 Very Important Person）","ex":{"en":"the VIP lounge","cn":"贵宾厅"}}]}},"villain":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"歹徒;恶棍;流氓","en":"A villain is someone who deliberately harms other people or breaks the law in order to get what he or she wants."},{"pos":"N-COUNT 可数名词","cn":"（小说、电影或戏剧中的）主要反面人物，反派主角","en":"The villain in a novel, film, or play is the main bad character."},{"pos":"PHRASE 短语","cn":"元凶;祸首;为害的人","en":"If you say that someone is the villain of the piece, you are saying in a slightly humorous way that they are seen by some people as the cause of all the trouble in a particular situation.","ex":{"en":"If Mr Denny is indeed the villain of the piece, as the police claim he is, he should have been more carefully watched.","cn":"如果丹尼先生真像警察说的那样是犯罪元凶，就应该对其进行更加严密的监视。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the bad person in a story, film, play etc, especially someone who breaks the law or who is cruel to others","cn":""},{"en":"someone who is so violent and dangerous that people think their behaviour is impossible to understand or forgive","cn":""},{"en":"someone who is thought to be bad or evil, especially because his sexual behaviour is unnatural or offensive","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A villain is a bad person — real or made up. In books, movies, current events, or history, the villain is the character who does mean, evil things on purpose."}]},"collocations":{"phrases":["ADJ. pantomime He wore a black cloak, like a pantomime villain.","VERB + VILLAIN cast sb as She seems to have cast me as the villain in her latest emotional upheaval. | play He has played villains in most o","PHRASES the villain of the piece/story He changed his story to make his wife appear the villain of the piece."]},"media":{"uk":"media/ldoce/hwd/bre/7/villain0205.mp3","us":"media/ldoce/hwd/ame/d/villain.mp3"},"examples":[{"en":"Industrialized nations are the real environmental villains.","cn":"工业化国家是破坏环境的真正元凶。"},{"en":"the heroes and villains of the 20th century * 20","cn":"世纪的英雄豪杰与罪魁祸首"}],"oxford":{"phon":"ˈvɪlən","pos":"noun","senses":[{"en":"the main bad character in a story, play, etc.","cn":"（小说、戏剧等中的）主要反面人物，反派主角，坏人","ex":{"en":"He often plays the part of the villain.","cn":"他经常扮演反面人物。"}},{"en":"a person who is morally bad or responsible for causing trouble or harm","cn":"恶棍；坏蛋","ex":{"en":"the heroes and villains of the 20th century","cn":"20 世纪的英雄豪杰与罪魁祸首"}},{"en":"a criminal","cn":"罪犯","lab":"informal","ex":{"en":"The police still haven't caught the villain.","cn":"警方至今还没有抓住那个歹徒。"}}]}},"virgo":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"室女宫，室女座（黄道十二宫之一。出生于8月23日至9月22日之间的人属此星座）","en":"Virgo is one of the twelve signs of the zodiac. Its symbol is a young woman. People who are born approximately between the 23rd of August and the 22nd of September come under this sign."},{"pos":"N-COUNT 可数名词","cn":"出生于室女宫时段的人","en":"A Virgo is a person whose sign of the zodiac is Virgo."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the study of the positions and movements of the stars and how they might influence people and events","cn":""},{"en":"a description of people’s characters and the things that will happen to them, based on the position of the stars and planets at the time of their birth – especially a description that is printed in a newspaper or magazine","cn":""},{"en":"the twelve signs that you can belong to according to your birth date and the position of the stars then, which some people believe influence our characters and our lives","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/3/brelasdevirgo.mp3","us":"media/ldoce/hwd/ame/2/virgo.mp3"},"oxford":{"phon":"ˈvɜːɡəʊ","pos":"noun","senses":[{"en":"the 6th sign of the zodiac, the Virgin","cn":"黄道第六宫；室女宫；室女（星）座；处女（星）座","g":"[uncountable]"},{"en":"a person born when the sun is in this sign, that is between 23 August and 23 September, approximately","cn":"处女座的人（约出生于 8 月 23 日至 9 月 23 日）","g":"[countable]"}]}},"visitation":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（上帝等神灵的）显现，出现","en":"A visitation is an event in which God or another non-human being seems to appear to someone or contact them.","ex":{"en":"The young people have claimed almost daily visitations from the Virgin Mary.","cn":"这些年轻人说几乎每天都会看到圣母马利亚显圣。"}},{"pos":"N-COUNT 可数名词","cn":"视察;巡视;光临;到访（幽默的说法）","en":"People sometimes refer humorously to a visit from someone, especially from someone in authority, as a visitation .","ex":{"en":"They had another visitation from Essex police.","cn":"埃塞克斯的警察再次拜访了他们。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（正式的）访问,探访，视察","en":"Visitation is the act of officially visiting someone.","ex":{"en":"House-to-house visitation has been carried on, under the regulations of the General Board of Health","cn":"根据卫生委员会的规定，挨家挨户的探访持续进行了下去。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an official visit to a place or person","cn":"视察﹐巡视﹔探访﹐探望"},{"en":"an occasion when a parent is allowed to spend time with the children after a divorce , or the right to do this 〔","cn":"离婚父母对子女的〕探视﹐探视权"},{"en":"an occasion when God or a spirit is believed to appear to someone on Earth 〔","cn":"神灵等的〕显现﹐出现"}]},"vocab":{"pos":"n","senses":[{"en":"Use the noun visitation to describe a formal or official visit, like the city health inspector's yearly visitation to your favorite pizza place."}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41visitation.mp3","us":"media/ldoce/hwd/ame/d/visitation.mp3"},"examples":[{"en":"She is seeking more liberal visitation with her daughter.","cn":"她正在寻求对女儿更自由的探视权。"},{"en":"visitation rights","cn":"探视子女的权利"}],"oxford":{"phon":"ˌvɪzɪˈteɪʃn","pos":"noun","senses":[{"en":"the right of a parent who is divorced or separated from his or her partner to visit a child who is living with the partner","cn":"（离婚父母对子女的）探视权","g":"[uncountable]","lab":"North American English","ex":{"en":"She is seeking more liberal visitation with her daughter.","cn":"她正在争取对女儿有更自由的探视权。"}},{"en":"an official visit, especially to check that rules are being obeyed and everything is as it should be","cn":"视察；巡视","g":"[countable, uncountable]","lab":"formal"},{"en":"an unexpected appearance of something, for example a ghost","cn":"（神灵等的）显现，显示，出现","g":"[countable]","lab":"formal"},{"en":"a disaster that is believed to be a punishment from God","cn":"（视为上帝惩罚的）天灾，灾难，灾祸","g":"[countable]","lab":"formal","ex":{"en":"a visitation of plague","cn":"天降瘟疫"}}]}},"vivisection":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（动物）活体解剖","en":"Vivisection is the practice of using live animals for scientific experiments.","ex":{"en":"...a fierce opponent of vivisection.","cn":"动物活体解剖的激烈反对者"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to use someone or something in scientific tests in order to find out how they are affected when you do something to them","cn":""},{"en":"to do tests in which a group of people or animals use a product, take a drug etc in order to see what their reaction is","cn":""},{"en":"to test a person or a particular group of people to see if they have a particular illness or infection","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Vivisection means literally \"to cut up something that's alive,\" and it's the term used for operating on live animals for scientific research. The word is usually used by people who oppose the practice."}]},"media":{"uk":"media/ldoce/hwd/bre/e/vivisection0205.mp3","us":"media/ldoce/hwd/ame/4/vivisection.mp3"},"oxford":{"phon":"ˌvɪvɪˈsekʃn","pos":"noun","senses":[{"en":"the practice of doing experiments on live animals for medical or scientific research","cn":"活体解剖"}]}},"vivacious":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"活泼的;快活的;令人兴奋的;迷人的","en":"If you describe someone as vivacious, you mean that they are lively, exciting, and attractive.","ex":{"en":"She's beautiful, vivacious, and charming.","cn":"她漂亮活泼，魅力十足。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"cheerful and active","cn":""},{"en":"a woman or girl who is vivacious has a lot of energy and a happy and attractive manner","cn":""},{"en":"full of interest and energy, especially when talking to someone","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"A vivacious person is lively and spirited: a vivacious dancer might do a back-flip off the wall and then jump into the arms of her partner."}]},"media":{"uk":"media/ldoce/hwd/bre/9/vivacious0205.mp3","us":"media/ldoce/hwd/ame/3/vivacious.mp3"},"examples":[{"en":"He was charmed by her beauty and vivacity.","cn":"他被她的美丽与活泼迷住了。"},{"en":"He had three pretty, vivacious daughters.","cn":"他有三个活泼漂亮的女儿。"}],"oxford":{"phon":"vɪˈveɪʃəs","pos":"adjective","senses":[{"en":"having a lively, attractive personality","cn":"可爱的；活泼的；动人的","ex":{"en":"He had three pretty, vivacious daughters.","cn":"他有三个活泼漂亮的女儿。"}}]}},"vise":{"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the American spelling of vice vice","cn":"的美式拼法"}]},"vocab":{"pos":"n","senses":[{"en":"If you’re going to be doing a lot of woodworking, you’ll probably need a vise , a tool used to clamp pieces of wood in place while you work on them."}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41vise.mp3","us":"media/ldoce/hwd/ame/f/ld41vise.mp3"},"examples":[{"en":"He held my arm in a vise-like (= very firm) grip.","cn":"他的手像老虎钳一样紧紧抓住了我的手臂。"}],"oxford":{"phon":"vaɪs","pos":"noun","senses":[{"en":"a tool with two metal blocks that can be moved together by turning a screw. The vise is used to hold an object in place while work is done on it.","cn":"台钳；虎钳","ex":{"en":"He held my arm in a vise-like (= very firm) grip.","cn":"他的手像虎钳一样紧紧抓住了我的手臂。"}}]}},"viagra":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"万艾可，伟哥（一种壮阳药）","en":"Viagra is a drug that is given to men with certain sexual problems in order to help them to have sexual intercourse."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a drug that helps men to have an erection","cn":"万艾可﹐威而钢〔帮助男性勃起的一种药物〕"}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41viagra.mp3","us":"media/ldoce/hwd/ame/c/laadviagra.mp3"},"oxford":{"phon":"vaɪˈæɡrə","pos":"noun","senses":[{"en":"a drug used to treat impotence in men","cn":"万艾可（一种治疗阳痿的药物）"}]}},"vigil":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"值夜；守夜（祈祷）；（夜间的）静默抗议","en":"A vigil is a period of time when people remain quietly in a place, especially at night, for example because they are praying or are making a political protest.","ex":{"en":"A prayer vigil is being held in the cathedral in memory of the bishop","cn":"为了纪念这位主教，教堂里正在举行守夜祈祷。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a period of time, especially during the night, when you stay awake in order to pray, remain with someone who is ill, or watch for danger 〔","cn":"尤指在夜间为了祈祷﹑守护病人或提防危险情况的〕守夜﹐值夜"},{"en":"a silent political protest in which people wait outside a building, especially during the night 〔","cn":"尤指夜间的〕静坐抗议"}]},"vocab":{"pos":"n","senses":[{"en":"A vigil is when you stay alert to guard something, as when you keep vigil over your hen house when the foxes are out, or a vigil can be solemn — as when a candlelight vigil is held for victims of a tragedy."}]},"collocations":{"phrases":["ADJ. all-night, constant, round-the-clock, 24-hour Since the accident, the boy's parents have kept a constant vigil at his bedside. | bedsid","VERB + VIGIL keep, maintain He told the gatekeeper to keep vigil.","PREP. ~ over the husband's vigil over his dying wife 2 silent political protest; time of prayer","ADJ. candlelight/candlelit, night-time, nocturnal Protesters held a candlelit vigil against the war. | silent a silent vigil outside the pre","VERB + VIGIL hold, stage | attend","PREP. ~ for a vigil for the murdered politician"]},"media":{"uk":"media/ldoce/hwd/bre/f/vigil0205.mp3","us":"media/ldoce/hwd/ame/0/vigil.mp3"},"examples":[{"en":"His parents kept a round-the-clock vigil at his bedside.","cn":"他父母日夜守护在他的床边。"},{"en":"Eva and Paul kept a constant vigil by their daughter’s hospital bedside.","cn":"伊娃和保罗一直在医院里守在女儿的病床边。"}],"oxford":{"phon":"ˈvɪdʒɪl","pos":"noun","senses":[{"en":"a period of time when people do not sleep, especially at night, in order to watch a sick person, say prayers, protest, etc.","cn":"（看护病人、祷告、抗议等的）不眠时间；（尤指）值夜，守夜祈祷","ex":{"en":"His parents kept a round-the-clock vigil at his bedside.","cn":"他父母日夜守护在他的床边。"}}]}},"villainy":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"恶行;犯罪行为","en":"Villainy is very bad or criminal behaviour.","ex":{"en":"They justify every villainy in the name of high ideals.","cn":"他们打着实现远大理想的幌子为他们的每件恶行开脱。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"evil or criminal behaviour","cn":"恶行﹔罪恶的行为"}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41villainy.mp3","us":"media/ldoce/hwd/ame/2/villainy.mp3"},"oxford":{"phon":"ˈvɪləni","pos":"noun","senses":[{"en":"immoral or cruel behaviour","cn":"邪恶行为；罪恶","ex":{"en":"At the end of the book, virtue is rewarded and villainy punished.","cn":"书的最后，善有善报，恶有恶报。"}}]}},"viva":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（大学的）口试","en":"A viva is a university examination in which a student answers questions in speech rather than writing."},{"pos":"EXCLAM 感叹语","cn":"万岁（表示支持的欢呼）","en":"People in crowds sometimes shout 'Viva!' before the name of a person or thing as a way of showing their support for them.","ex":{"en":"Some members of the huge crowd shouted 'Viva peace, viva.'","cn":"浩浩荡荡的人群中有些人呼喊“和平万岁！万岁！”的口号。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a spoken examination taken at the end of a university course 〔","cn":"大学中一门课程结束时的〕口试"},{"en":"used to show that you approve of someone and want them to continue to exist or be successful","cn":"万岁〔表示赞许或祝愿的欢呼声〕"}]},"media":{"uk":"media/ldoce/hwd/bre/3/viva_n0205.mp3","us":"media/ldoce/hwd/ame/7/ld44viva.mp3"},"oxford":{"phon":"ˈviːvə","pos":"exclamation","senses":[{"en":"used for expressing support for somebody or something","cn":"（表示拥护）万岁","ex":{"en":"Viva the revolution!","cn":"革命万岁！"}},{"en":"a spoken exam, especially in a British university","cn":"（尤指英国大学的）口试","pos":"noun"}]}},"videodisc":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a round flat piece of plastic used in the past to record and show films or programmes in the same way as a video","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41videodisc.mp3","us":"media/ldoce/hwd/ame/7/ld41videodisc.mp3"},"oxford":{"phon":"ˈvɪdiəʊdɪsk","pos":"noun","senses":[{"en":"a plastic disc that you can record films and programmes on, for showing on a television screen","cn":"视盘；影碟"}]}}});
